package com.dianping.shopdetail.service;

import com.dianping.shopdetail.exception.DuplicateRecommendDishException;
import com.dianping.shopdetail.exception.RecommendDishException;
import com.dianping.shopdetail.model.RecommendDish;
import com.dianping.shopdetail.model.request.PublishRecommendDishRequest;
import com.dianping.shopdetail.model.request.RecommendDishPageRequest;
import com.dianping.shopdetail.model.result.RecommendDishItem;
import com.dianping.shopdetail.model.result.RecommendDishPageResult;
import com.dianping.shopdetail.repository.RecommendDishRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.List;
import java.util.Set;

/**
 * 推荐菜独立用例；事务内同时维护推荐关系和人数，不依赖任务链。
 */
@Service
public class RecommendDishApplicationService {
    /**
     * 推荐菜与用户推荐关系仓储。
     */
    private final RecommendDishRepository repository;
    /**
     * 业务写入事务模板。
     */
    private final TransactionTemplate write;
    /**
     * 独立只读事务模板。
     */
    private final TransactionTemplate read;

    /**
     * 创建 RecommendDishApplicationService，初始化所需依赖及实例状态。
     *
     * @param repository 业务仓储
     * @param manager Spring 事务管理器
     */
    public RecommendDishApplicationService(RecommendDishRepository repository, PlatformTransactionManager manager) {
        this.repository = repository;
        write = transaction(manager, false);
        read = transaction(manager, true);
    }

    /**
     * 创建当前用例使用的独立事务模板，配置读取或写入需要的隔离级别。
     *
     * @param manager Spring 事务管理器
     * @param readOnly 是否创建只读事务
     * @return 已配置只读标记与隔离级别的事务模板
     */
    private static TransactionTemplate transaction(PlatformTransactionManager manager, boolean readOnly) {
        var transaction = new TransactionTemplate(manager);
        transaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
        // 写入由行锁保护，锁等待结束后读取最新提交；分页统计与列表使用同一快照。
        transaction.setIsolationLevel(readOnly ? TransactionDefinition.ISOLATION_REPEATABLE_READ
                : TransactionDefinition.ISOLATION_READ_COMMITTED);
        transaction.setReadOnly(readOnly);
        return transaction;
    }

    /**
     * 发布推荐菜并原子维护作者首次推荐关系与人数。
     *
     * @param shopId 店铺标识
     * @param userId 服务端确认的用户标识
     * @param request 已经定义字段约束的业务请求
     * @return 新建或幂等重放的发布结果
     */
    public RecommendDishItem publish(Long shopId, Long userId, PublishRecommendDishRequest request) {
        requireUser(userId);
        if (request == null) throw new RecommendDishException(400, "请求不得为空");
        RecommendDish submitted = request.toDish(shopId, userId);
        try {
            return write.execute(status -> {
                // 同店新增先锁店铺，再检查重名并插入，保证并发创建按顺序完成。
                if (!repository.lockShop(shopId)) throw new RecommendDishException(404, "店铺不存在");
                var existing = repository.findSubmission(userId, submitted.requestId());
                if (existing.isPresent()) return replay(existing.get(), submitted);
                if (repository.findByName(shopId, submitted.name()).isPresent()) throw nameConflict();
                Long id = repository.insert(submitted);
                repository.insertRecommendation(id, userId);
                repository.incrementRecommendationCount(id);
                return RecommendDishItem.from(repository.findById(shopId, id).orElseThrow(), true);
            });
        } catch (DuplicateRecommendDishException conflict) {
            // 原事务已回滚；跨店铺的同提交标识竞争使用新事务读取胜出记录。
            return read.execute(status -> {
                var existing = repository.findSubmission(userId, submitted.requestId());
                if (existing.isPresent()) return replay(existing.get(), submitted);
                if (repository.findByName(shopId, submitted.name()).isPresent()) throw nameConflict();
                throw conflict;
            });
        }
    }

    /**
     * 为当前用户增加一次去重推荐，重复请求不重复增加推荐人数。
     *
     * @param shopId 店铺标识
     * @param dishId 菜品标识
     * @param userId 服务端确认的用户标识
     * @return 包含最新推荐人数及当前用户推荐状态的菜品响应
     */
    public RecommendDishItem recommend(Long shopId, Long dishId, Long userId) {
        requireUser(userId);
        requirePositive(shopId, "店铺");
        requirePositive(dishId, "菜品");
        return write.execute(status -> {
            if (repository.lockDish(shopId, dishId).isEmpty()) throw new RecommendDishException(404, "当前店铺不存在该菜品");
            if (!repository.hasRecommendation(dishId, userId)) {
                repository.insertRecommendation(dishId, userId);
                repository.incrementRecommendationCount(dishId);
            }
            return RecommendDishItem.from(repository.findById(shopId, dishId).orElseThrow(), true);
        });
    }

    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param request 已经定义字段约束的业务请求
     * @param userId 服务端确认的用户标识
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    public RecommendDishPageResult page(RecommendDishPageRequest request, Long userId) {
        if (request == null) throw new RecommendDishException(400, "请求不得为空");
        return read.execute(status -> {
            if (!repository.shopExists(request.shopId())) throw new RecommendDishException(404, "店铺不存在");
            long total = repository.countByShopId(request.shopId());
            List<RecommendDish> dishes = request.offset() >= total ? List.of()
                    : repository.page(request.shopId(), request.offset(), request.size());
            Set<Long> recommended = userId == null || dishes.isEmpty() ? Set.of()
                    : repository.recommendedIds(userId, dishes.stream().map(RecommendDish::id).toList());
            var items = dishes.stream().map(dish -> RecommendDishItem.from(dish, recommended.contains(dish.id()))).toList();
            return new RecommendDishPageResult(items, total, request.current(), request.size(),
                    total == 0 ? 0 : 1 + (total - 1) / request.size());
        });
    }

    /**
     * 检查幂等记录的提交内容一致性并返回已有结果。
     *
     * @param existing 已持久化的同提交标识记录
     * @param submitted 本次提交并完成规范化的内容
     * @return 相同提交标识对应的既有菜品响应
     */
    private static RecommendDishItem replay(RecommendDish existing, RecommendDish submitted) {
        if (!existing.sameSubmission(submitted)) throw new RecommendDishException(409, "提交标识已用于其他菜品内容，请重新提交");
        return RecommendDishItem.from(existing, true);
    }
    /**
     * 创建同店同名菜品冲突的业务错误，引导用户推荐已有菜品。
     *
     * @return 提示同店同名菜品已存在的业务冲突异常
     */
    private static RecommendDishException nameConflict() {
        return new RecommendDishException(409, "该店已收录同名菜品，请在推荐菜列表中找到它并点击“我也推荐”");
    }
    /**
     * 校验写操作所需的可信登录身份。
     *
     * @param userId 服务端确认的用户标识
     */
    private static void requireUser(Long userId) {
        if (userId == null || userId <= 0) throw new RecommendDishException(401, "请先登录");
    }
    /**
     * 校验业务标识为正数。
     *
     * @param id 记录标识
     * @param label 校验错误中使用的业务对象名称
     */
    private static void requirePositive(Long id, String label) {
        if (id == null || id <= 0) throw new RecommendDishException(400, label + "标识必须为正数");
    }
}

package com.dianping.shopdetail.service;

import com.dianping.shared.taskchain.enums.*;
import com.dianping.shared.taskchain.model.PhaseConfig;
import com.dianping.shared.taskchain.service.TaskChainEngine;
import com.dianping.shopdetail.exception.ShopDetailException;
import com.dianping.shopdetail.model.ShopDetailAggregate;
import com.dianping.shopdetail.model.request.ShopDetailPageRequest;
import com.dianping.shopdetail.model.result.ShopDetailResult;
import com.dianping.shopdetail.task.ShopDetailTaskContext;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.lang.Nullable;
import org.springframework.stereotype.Service;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.TimeoutException;

/**
 * 商详首次展示用例：选择执行路径、编排任务并检查执行结果。
 */
@Service
public class ShopDetailApplicationService {
    /**
     * 共享任务链引擎；允许未装配。
     */
    private final TaskChainEngine engine;
    /**
     * 商详领域服务。
     */
    private final ShopDetailDomainService domain;
    /**
     * 商详任务链阶段的执行配置。
     */
    private final List<PhaseConfig> phases;

    /**
     * 创建 ShopDetailApplicationService，初始化所需依赖及实例状态。
     * @param engine 共享任务链引擎；允许未装配
     * @param domain 商详领域服务
     * @param queryTimeout 并行查询阶段总预算，单位为毫秒
     * @param postTimeout 后处理阶段共享预算，单位为毫秒
     */
    public ShopDetailApplicationService(@Nullable TaskChainEngine engine, ShopDetailDomainService domain,
            @Value("${shop-detail.query-timeout-ms:2000}") long queryTimeout,
            @Value("${shop-detail.post-timeout-ms:1000}") long postTimeout) {
        this.engine = engine;
        this.domain = domain;
        phases = List.of(
                new PhaseConfig(ProcessPhase.DATA_PROCESSING, ExecutionMode.PARALLEL, Duration.ofMillis(queryTimeout)),
                new PhaseConfig(ProcessPhase.POST_PROCESSING, ExecutionMode.SERIAL, Duration.ofMillis(postTimeout)));
    }

    /**
     * 选择任务链或同步聚合路径，检查必需结果并转换六区响应及对外错误
     * @param shopId 店铺标识
     * @param viewerId 当前浏览者标识；游客传入 {@code null}
     * @return 包含六个展示区域及各分项状态的商详响应
     * @throws ShopDetailException 输入非法、店铺不存在，或必需查询失败、超时
     */
    public ShopDetailResult getShopDetail(Long shopId, Long viewerId) {
        new ShopDetailPageRequest(shopId, 1, 1);
        ShopDetailAggregate detail;
        if (engine == null) {
            try {
                detail = domain.getShopDetail(shopId, viewerId);
            } catch (RuntimeException error) {
                throw failure(shopId, error);
            }
        } else {
            var context = engine.executePhaseChain(ShopDetailTaskContext.GROUP,
                    new ShopDetailTaskContext(shopId, viewerId), phases);
            ensureSuccess(context);
            return ShopDetailResult.from(context.getOutput(), context.sectionResults());
        }
        return ShopDetailResult.from(detail);
    }

    /**
     * 校验必需任务执行状态与输出，转换为商详用例错误。
     *
     * @param context 当前调用独立使用的任务上下文
     */
    private void ensureSuccess(ShopDetailTaskContext context) {
        if (!context.isSuccess()) {
            throw failure(context.getShopId(), context.getError());
        }
        if (context.getOutput() == null) throw new ShopDetailException(503, "商详未生成有效结果");
    }

    /**
     * 两种执行路径使用相同的用例异常边界，不暴露底层错误。
     *
     * @param shopId 店铺标识
     * @param error 导致失败的异常；没有异常时为 {@code null}
     * @return 保留已知业务状态或转换为 503、504 的商详异常
     */
    private ShopDetailException failure(Long shopId, Throwable error) {
        org.apache.commons.logging.LogFactory.getLog(getClass()).error("商详必需查询失败，shopId=" + shopId, error);
        if (error instanceof ShopDetailException known) return known;
        return new ShopDetailException(error instanceof TimeoutException ? 504 : 503,
                "商详暂时不可用，请稍后重试", error);
    }
}

package com.dianping.shopdetail.service;

import com.dianping.shopdetail.model.request.ShopDetailPageRequest;
import com.dianping.shopdetail.model.result.*;
import com.dianping.shopdetail.model.result.ShopDetailResult.*;
import org.springframework.stereotype.Service;

/**
 * 独立“查看更多”用例；首屏任务链直接调用领域服务。
 */
@Service
public class ShopDetailQueryService {
    /**
     * 商详领域服务。
     */
    private final ShopDetailDomainService domain;
    /**
     * 创建 ShopDetailQueryService，初始化所需依赖及实例状态。
     *
     * @param domain 商详领域服务
     */
    public ShopDetailQueryService(ShopDetailDomainService domain) { this.domain = domain; }

    /**
     * 读取优惠券，沿用上架、有效期和可购买优先的展示规则。
     *
     * @param request 已经定义字段约束的业务请求
     * @return 优惠券的分页结果，包含总数与当前页记录
     */
    public ShopPageResult<VoucherItem> vouchers(ShopDetailPageRequest request) {
        domain.base(request.shopId());
        return ShopPageResult.from(domain.vouchers(request.shopId(), request.current(), request.size()), VoucherItem::from);
    }

    /**
     * 读取当前店铺的探店笔记，并按显式传入的身份补齐点赞状态。
     *
     * @param request 已经定义字段约束的业务请求
     * @param viewerId 当前浏览者标识；游客传入 {@code null}
     * @return 探店笔记及当前浏览者点赞状态的分页结果，包含总数与当前页记录
     */
    public ShopPageResult<BlogItem> blogs(ShopDetailPageRequest request, Long viewerId) {
        domain.base(request.shopId());
        return ShopPageResult.from(domain.blogs(request.shopId(), request.current(), request.size(), viewerId), BlogItem::from);
    }

    /**
     * 以当前店铺为中心读取五公里内同类型店铺，排除自身并按距离、标识排序。
     *
     * @param request 已经定义字段约束的业务请求
     * @return 带可用状态的周边分页结果
     */
    public SectionResult<ShopPageResult<RelatedItem>> related(ShopDetailPageRequest request) {
        var center = domain.base(request.shopId());
        var reason = domain.relatedUnavailableReason(center);
        if (reason != null) return SectionResult.unavailable("UNAVAILABLE", reason);
        return SectionResult.attempt(() -> domain.related(center, request.current(), request.size()),
                page -> page.records().isEmpty()).map(page -> ShopPageResult.from(page, RelatedItem::from));
    }
}

package com.dianping.shopdetail.service;

import com.dianping.shopdetail.enums.ReviewTag;
import com.dianping.shopdetail.exception.DuplicateReviewSubmissionException;
import com.dianping.shopdetail.exception.ShopReviewException;
import com.dianping.shopdetail.model.*;
import com.dianping.shopdetail.model.request.*;
import com.dianping.shopdetail.model.result.*;
import com.dianping.shopdetail.repository.ShopReviewRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.Arrays;
import java.util.List;
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 用例编排与事务边界；不读取 HTTP 或线程本地身份。
 */
@Service
public class ShopReviewApplicationService {
    /**
     * 店铺评价仓储。
     */
    private final ShopReviewRepository repository;
    /**
     * 业务写入事务模板。
     */
    private final TransactionTemplate write;
    /**
     * 独立只读事务模板。
     */
    private final TransactionTemplate read;

    /**
     * 创建 ShopReviewApplicationService，初始化所需依赖及实例状态。
     *
     * @param repository 业务仓储
     * @param manager Spring 事务管理器
     */
    public ShopReviewApplicationService(ShopReviewRepository repository, PlatformTransactionManager manager) {
        this.repository = repository;
        write = transaction(manager, false);
        read = transaction(manager, true);
    }
    /**
     * 创建当前用例使用的独立事务模板，配置读取或写入需要的隔离级别。
     *
     * @param manager Spring 事务管理器
     * @param readOnly 是否创建只读事务
     * @return 已配置只读标记与隔离级别的事务模板
     */
    private static TransactionTemplate transaction(PlatformTransactionManager manager, boolean readOnly) {
        var template = new TransactionTemplate(manager);
        template.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
        template.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);
        template.setReadOnly(readOnly);
        return template;
    }

    /**
     * 发布店铺评价，幂等记录、评价写入与店铺统计在同一事务完成。
     *
     * @param shopId 店铺标识
     * @param userId 服务端确认的用户标识
     * @param request 已经定义字段约束的业务请求
     * @return 新建或幂等重放的发布结果
     */
    public Long publish(Long shopId, Long userId, PublishShopReviewRequest request) {
        if (userId == null) throw new ShopReviewException(401, "请先登录");
        if (request == null) throw new ShopReviewException(400, "请求不得为空");
        var review = request.toReview(shopId, userId);
        try {
            return write.execute(status -> {
                // 锁定前不做普通查询，避免 MySQL 提前建立旧的一致性快照。
                if (!repository.lockShop(shopId)) throw new ShopReviewException(404, "店铺不存在");
                var existing = repository.findSubmission(userId, review.requestId());
                if (existing.isPresent()) return replay(existing.get(), review);
                Long id = repository.insert(review);
                long total = repository.countByShopId(shopId);
                int score = storedScore(total, repository.sumOverallScoreByShopId(shopId));
                repository.updateStatistics(shopId, score, Math.toIntExact(total));
                return id;
            });
        } catch (DuplicateReviewSubmissionException error) {
            // execute 抛出时失败事务已经回滚；用全新视图读取唯一键竞争的胜出记录。
            return read.execute(status -> replay(repository.findSubmission(userId, review.requestId())
                    .orElseThrow(() -> error), review));
        }
    }
    /**
     * 检查幂等记录的提交内容一致性并返回已有结果。
     *
     * @param existing 已持久化的同提交标识记录
     * @param submitted 本次提交并完成规范化的内容
     * @return 相同提交标识对应的既有评价标识
     */
    private static Long replay(ShopReview existing, ShopReview submitted) {
        if (!existing.sameSubmission(submitted)) throw new ShopReviewException(409, "提交标识已被不同评价内容使用");
        return existing.id();
    }

    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param request 已经定义字段约束的业务请求
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    public ShopReviewPageResult page(ShopReviewPageRequest request) {
        return read.execute(status -> {
            if (!repository.shopExists(request.shopId())) throw new ShopReviewException(404, "店铺不存在");
            long total = repository.countByShopId(request.shopId());
            int score = storedScore(total, repository.sumOverallScoreByShopId(request.shopId()));
            var reviews = request.offset() >= total ? List.<ShopReview>of()
                    : repository.page(request.shopId(), request.offset(), ShopReviewPageRequest.SIZE);
            var items = reviews.stream().map(ShopReviewItem::from).toList();
            return new ShopReviewPageResult(items, total, request.current(), ShopReviewPageRequest.SIZE,
                    (total + ShopReviewPageRequest.SIZE - 1) / ShopReviewPageRequest.SIZE,
                    total == 0 ? null : BigDecimal.valueOf(score, 1));
        });
    }

    /**
     * 从评分总和计算均分，保留内部十分之一分的精度，不使用历史均分反推。
     *
     * @param total 全部匹配记录数
     * @param scoreSum 按十倍保存的总体评分总和
     * @return 供店铺表存储的十倍整数总体均分
     */
    private static int storedScore(long total, long scoreSum) {
        if (total < 0 || total > Integer.MAX_VALUE || scoreSum < 0)
            throw new IllegalStateException("评价统计超出支持范围");
        return total == 0 ? 0 : BigDecimal.valueOf(scoreSum)
                .divide(BigDecimal.valueOf(total), 0, RoundingMode.HALF_UP).intValueExact();
    }
    /**
     * 读取供用户选择的固定评价标签词典。
     *
     * @return 系统预设评价标签的代码与中文名称列表
     */
    public List<ShopReviewTagOption> tags() {
        return Arrays.stream(ReviewTag.values()).map(tag -> new ShopReviewTagOption(tag.name(), tag.displayName())).toList();
    }
}

package com.dianping.shopdetail.service;

import com.dianping.shopdetail.model.result.ShopSetmealResult;
import com.dianping.shopdetail.exception.ShopSetmealException;
import com.dianping.shopdetail.repository.ShopSetmealRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.List;

/**
 * 在同一只读快照内编排套餐主信息与明细查询。
 */
@Service
public class ShopSetmealApplicationService {
    /**
     * 店铺套餐仓储。
     */
    private final ShopSetmealRepository repository;
    /**
     * 独立只读事务模板。
     */
    private final TransactionTemplate read;

    /**
     * 创建 ShopSetmealApplicationService，初始化所需依赖及实例状态。
     *
     * @param repository 业务仓储
     * @param manager Spring 事务管理器
     */
    public ShopSetmealApplicationService(ShopSetmealRepository repository, PlatformTransactionManager manager) {
        this.repository = repository;
        read = new TransactionTemplate(manager);
        read.setReadOnly(true);
        read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);
    }

    /**
     * 读取店铺上架套餐及明细，沿用公开查询参数约束。
     *
     * @param shopId 店铺标识
     * @return 包含固定菜品明细的上架套餐列表
     */
    public List<ShopSetmealResult> list(Long shopId) {
        if (shopId == null || shopId <= 0) throw new ShopSetmealException(400, "店铺 ID 必须为正整数");
        return read.execute(status -> {
            if (!repository.shopExists(shopId)) throw new ShopSetmealException(404, "店铺不存在");
            return repository.findPublishedByShopId(shopId).stream().map(ShopSetmealResult::from).toList();
        });
    }

    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param request 已经定义字段约束的业务请求
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    public com.dianping.shopdetail.model.result.ShopPageResult<ShopSetmealResult> page(
            com.dianping.shopdetail.model.request.ShopDetailPageRequest request) {
        return read.execute(status -> {
            if (!repository.shopExists(request.shopId())) throw new ShopSetmealException(404, "店铺不存在");
            var page = new com.dianping.shopdetail.model.ShopPage<>(
                    repository.pagePublished(request.shopId(), request.offset(), request.size()),
                    repository.countPublished(request.shopId()), request.current(), request.size());
            return com.dianping.shopdetail.model.result.ShopPageResult.from(page, ShopSetmealResult::from);
        });
    }
}

package com.dianping.shopdetail.task;

import com.dianping.shared.taskchain.annotation.TaskNode;
import com.dianping.shared.taskchain.enums.*;
import com.dianping.shared.taskchain.model.*;
import com.dianping.shopdetail.model.ShopDetailAggregate;
import org.springframework.stereotype.Component;

/**
 * 汇集已完成的业务数据，执行状态保留在上下文中。
 */
@Component
@TaskNode(nodeId="assemble", group=ShopDetailTaskContext.GROUP, phase=ProcessPhase.POST_PROCESSING,
        order=10, taskType=TaskType.CPU_BOUND, required=true)
public class AssembleShopDetailNode implements TaskNodeHandler<Long, ShopDetailAggregate> {
    /**
     * 执行当前节点，只通过节点上下文提交结果；失败或超时的写集由引擎丢弃。
     *
     * @param value 待读取或转换的值
     */
    @Override public void execute(TaskContext<Long, ShopDetailAggregate> value) {
        var context = (ShopDetailTaskContext) value;
        if (context.getBase() == null) throw new IllegalStateException("基础查询未生成店铺资料");
        context.setOutput(ShopDetailAggregate.builder().shop(context.getBase())
                .vouchers(context.data("vouchers")).setmeals(context.data("setmeals"))
                .recommendations(context.data("recommendations"))
                .recommendedIds(context.data("recommendationState"))
                .reviews(context.data("reviews")).reviewSummary(context.data("statistics"))
                .blogs(context.data("blogs")).build());
    }
}

package com.dianping.shopdetail.task;

import com.dianping.shared.taskchain.annotation.TaskNode;
import com.dianping.shared.taskchain.enums.*;
import com.dianping.shared.taskchain.model.*;
import com.dianping.shopdetail.model.*;
import com.dianping.shopdetail.model.result.SectionResult;
import com.dianping.shopdetail.service.ShopDetailDomainService;
import org.springframework.stereotype.Component;
import java.util.List;

/**
 * 领域服务生成衍生数据，节点只维护各项执行状态及提交边界。
 */
@Component
@TaskNode(nodeId="enrich",
        group=ShopDetailTaskContext.GROUP,
        phase=ProcessPhase.POST_PROCESSING,
        order=20,
        taskType=TaskType.IO_BOUND,
        required=false)
public class EnrichShopDetailNode implements TaskNodeHandler<Long, ShopDetailAggregate> {
    /**
     * 商详领域服务。
     */
    private final ShopDetailDomainService domain;
    /**
     * 创建 EnrichShopDetailNode，初始化所需依赖及实例状态。
     *
     * @param domain 商详领域服务
     */
    public EnrichShopDetailNode(ShopDetailDomainService domain) { this.domain = domain; }

    /**
     * 执行当前节点，只通过节点上下文提交结果；失败或超时的写集由引擎丢弃。
     *
     * @param value 待读取或转换的值
     */
    @Override public void execute(TaskContext<Long, ShopDetailAggregate> value) {
        var context = (ShopDetailTaskContext) value;
        var review = SectionResult.attempt(() -> domain.reviewEvidence(context.getShopId(), context.getSince()), List::isEmpty);
        var blog = SectionResult.attempt(() -> domain.blogEvidence(context.getShopId(), context.getSince()), List::isEmpty);
        SectionResult<List<ShopDecisionTag>> tags;
        if (!review.available() && !blog.available()) {
            tags = SectionResult.unavailable("FAILED", "近期口碑标签暂不可用");
        } else {
            tags = SectionResult.attempt(() -> domain.mergeDecisionTags(
                    review.available() ? review.data() : List.of(), blog.available() ? blog.data() : List.of()), List::isEmpty);
            if (tags.available() && (!review.available() || !blog.available()))
                tags = new SectionResult<>("PARTIAL", tags.data(), "部分来源不可用，统计不完整");
        }
        var reviewTags = review.available()
                ? SectionResult.attempt(() -> domain.mergeDecisionTags(review.data(), List.of()), List::isEmpty)
                : SectionResult.<List<ShopDecisionTag>>unavailable("FAILED", "近期评价标签暂不可用");
        // 可选节点必须复制后再赋值，超时后才能安全丢弃整个节点的写入。
        var aggregate = context.getOutput().toBuilder().build();
        var reason = domain.relatedUnavailableReason(aggregate.getShop());
        var related = reason == null
                ? SectionResult.attempt(() -> domain.related(aggregate.getShop(), 1, 6), page -> page.records().isEmpty())
                : SectionResult.<ShopPage<ShopRelatedShop>>unavailable("UNAVAILABLE", reason);
        context.put("decisionTags", tags);
        context.put("reviewTags", reviewTags);
        context.put("relatedShops", related);
        aggregate.setDecisionTags(tags.data());
        aggregate.setReviewTags(reviewTags.data());
        aggregate.setRelatedShops(related.data());
        aggregate.setRelatedUnavailableReason(reason);
        context.setOutput(aggregate);
    }
}

