     * 应用用例服务。
     */
    ShopDetailApplicationService service;
    /**
     * 店铺基础资料。
     */
    final ShopBaseInfo shop=new ShopBaseInfo(8L,"巷口咖啡",1L,"","商圈","地址",120.0,30.0,50L,"全天");

    /**
     * 通过上下文写集更新测试业务属性。
