package com.dianping.config;

import com.dianping.filter.JwtAuthenticationFilter;
import com.dianping.security.JwtProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpMethod;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.security.web.util.matcher.RegexRequestMatcher;

@Configuration
@EnableWebSecurity
@EnableConfigurationProperties(JwtProperties.class)
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtAuthenticationFilter;

    public SecurityConfig(JwtAuthenticationFilter jwtAuthenticationFilter) {
        this.jwtAuthenticationFilter = jwtAuthenticationFilter;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
                .csrf(csrf -> csrf.disable())
                .formLogin(form -> form.disable())
                .httpBasic(basic -> basic.disable())
                .logout(logout -> logout.disable())
                .sessionManagement(session -> session
                        .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .exceptionHandling(exceptions -> exceptions
                        .authenticationEntryPoint((request, response, exception) ->
                                response.sendError(HttpServletResponse.SC_UNAUTHORIZED)))
                .authorizeHttpRequests(authorize -> authorize
                        .requestMatchers(HttpMethod.POST, "/shop/*/reviews").authenticated()
                        .requestMatchers(HttpMethod.POST, "/shop/*/recommend-dishes").authenticated()
                        .requestMatchers(HttpMethod.PUT, "/shop/*/recommend-dishes/*/recommendation").authenticated()
                        .requestMatchers(
                                "/user/login/code",
                                "/user/register/code",
                                "/user/register",
                                "/user/login",
                                "/user/refresh",
                                "/user/logout",
                                "/shop/review-tags",
                                "/shop/*/reviews",
                                "/shop/**",
                                "/voucher/**",
                                "/shop-type/**",
                                "/blog/hot",
                                "/v3/api-docs/**",
                                "/swagger-ui/**",
                                "/swagger-ui.html",
                                "/error",
                                "/blog/hot",
                                "/blog/view/**")
                        .permitAll()
                        .requestMatchers(HttpMethod.GET, "/blog/*/comments")
                        .permitAll()
                        .requestMatchers(HttpMethod.POST, "/blog/*/visit", "/shop/*/visit")
                        .permitAll()
                        .requestMatchers(RegexRequestMatcher.regexMatcher(
                                HttpMethod.GET, "^/user/[0-9]+$"))
                        .permitAll()
                        .requestMatchers(HttpMethod.GET, "/blog/of/user")
                        .permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthenticationFilter,
                        UsernamePasswordAuthenticationFilter.class)
                .build();
    }
}

