package com.dianping.controller;

import com.dianping.dto.UserDTO;
import com.dianping.result.Result;
import com.dianping.shopdetail.RecommendDishFacade;
import com.dianping.shopdetail.model.request.PublishRecommendDishRequest;
import com.dianping.shopdetail.model.request.RecommendDishPageRequest;
import com.dianping.shopdetail.model.result.RecommendDishItem;
import com.dianping.shopdetail.model.result.RecommendDishPageResult;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

/**
 * 独立推荐菜接口；HTTP 层只处理身份、请求绑定和统一响应。
 */
@RestController
@RequestMapping("/shop/{shopId}/recommend-dishes")
public class RecommendDishController {
    /**
     * 当前业务门面。
     */
    private final RecommendDishFacade facade;
    /**
     * 创建 RecommendDishController，初始化所需依赖及实例状态。
     *
     * @param facade 当前业务门面
     */
    public RecommendDishController(RecommendDishFacade facade) { this.facade = facade; }

    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param shopId 店铺标识
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @param user 服务端认证得到的用户；游客为 {@code null}
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    @GetMapping
    public Result<RecommendDishPageResult> page(@PathVariable Long shopId,
            @RequestParam(defaultValue = "1") Long current, @RequestParam(defaultValue = "12") Integer size,
            @AuthenticationPrincipal UserDTO user) {
        return Result.success(facade.page(new RecommendDishPageRequest(shopId, current, size), user == null ? null : user.getId()));
    }

    /**
     * 发布推荐菜并原子维护作者首次推荐关系与人数。
     *
     * @param shopId 店铺标识
     * @param user 服务端认证得到的用户；游客为 {@code null}
     * @param request 已经定义字段约束的业务请求
     * @return 新建或幂等重放的发布结果
     */
    @PostMapping
    public Result<RecommendDishItem> publish(@PathVariable Long shopId, @AuthenticationPrincipal UserDTO user,
            @RequestBody PublishRecommendDishRequest request) {
        return Result.success(facade.publish(shopId, user == null ? null : user.getId(), request));
    }

    /**
     * 为当前用户增加一次去重推荐，重复请求不重复增加推荐人数。
     *
     * @param shopId 店铺标识
     * @param dishId 菜品标识
     * @param user 服务端认证得到的用户；游客为 {@code null}
     * @return 包含最新推荐人数及当前用户推荐状态的菜品响应
     */
    @PutMapping("/{dishId}/recommendation")
    public Result<RecommendDishItem> recommend(@PathVariable Long shopId, @PathVariable Long dishId,
            @AuthenticationPrincipal UserDTO user) {
        return Result.success(facade.recommend(shopId, dishId, user == null ? null : user.getId()));
    }
}

package com.dianping.controller;


import org.springframework.util.StringUtils;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;

import com.dianping.constant.SystemConstants;
import com.dianping.result.Result;
import com.dianping.entity.Shop;
import com.dianping.exception.InvalidShopGeoQueryException;
import com.dianping.service.ShopService;
import com.dianping.service.ShopGeoValidator;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import org.springframework.web.bind.annotation.*;

import jakarta.annotation.Resource;
import java.util.List;


@RestController
@RequestMapping("/shop")
@Tag(name = "商铺接口")
public class ShopController {

    @Resource
    public ShopService shopService;

    /**
     * 根据id查询商铺信息
     * @param id 商铺id
     * @return 商铺详情数据
     */
    @GetMapping("/{id}")
    @Operation(summary = "根据 ID 查询商铺")
    public Result<Shop> queryShopById(@PathVariable("id") Long id) {

        return shopService.queryById(id);
    }

    /**
     * 新增商铺信息
     * @param shop 商铺数据
     * @return 商铺id
     */
    @PostMapping
    @Operation(summary = "新增商铺")
    public Result<Long> saveShop(@RequestBody Shop shop) {
        // 写入数据库
        shopService.save(shop);
        // 返回店铺id
        return Result.success(shop.getId());
    }

    /**
     * 更新商铺信息
     * @param shop 商铺数据
     * @return 无
     */
    @PutMapping
    @Operation(summary = "更新商铺")
    public Result<Void> updateShop(@RequestBody Shop shop) {

        return shopService.update(shop) ;
    }

    /**
     * 按类型分页查询门店
     * @param typeId 店铺类型id
     * @param current 当前页码
     * @param sort 排序方式  距离、人气、评分
     * @param longitude 经度
     * @param latitude 纬度
     * @return 符合的店铺列表
     */
    @GetMapping("/of/type")
    @Operation(summary = "按类型分页查询门店")
    public Result<List<Shop>> queryShopByType(
            @RequestParam("typeId") Integer typeId,
            @RequestParam(value = "current", defaultValue = "1") Integer current,
            @RequestParam(value = "sort", defaultValue = "comments") String sort,
            @RequestParam(value = "longitude", required = false) Double longitude,
            @RequestParam(value = "latitude", required = false) Double latitude
    ) {//先检查经纬度是否合法
        if ("distance".equals(sort) && !ShopGeoValidator.isValidCoordinate(longitude, latitude)) {
            throw new InvalidShopGeoQueryException();
        }//调用服务层
        return shopService.queryByType(typeId, current, sort, longitude, latitude);
    }

    /**
     * 根据商铺名称关键字分页查询商铺信息
     * @param name 商铺名称关键字
     * @param current 页码
     * @return 商铺列表
     */
    @GetMapping("/of/name")
    @Operation(summary = "按名称分页查询门店")
    public Result<List<Shop>> queryShopByName(
            @RequestParam(value = "name", required = false) String name,
            @RequestParam(value = "current", defaultValue = "1") Integer current
    ) {
        // 根据类型分页查询
        Page<Shop> page = shopService.query()
                .like(StringUtils.hasText(name), "name", name)
                .page(new Page<>(current, SystemConstants.MAX_PAGE_SIZE));
        // 返回数据
        return Result.success(page.getRecords());
    }
}

