            @AuthenticationPrincipal UserDTO user) {
        return Result.success(facade.blogs(new ShopDetailPageRequest(shopId,current,size),user==null?null:user.getId()));
    }
    /**
     * 以当前店铺为中心读取五公里内同类型店铺，排除自身并按距离、标识排序。
     *
     * @param shopId 店铺标识
