package com.dianping.shared.taskchain.annotation;

import com.dianping.shared.taskchain.enums.ProcessPhase;
import com.dianping.shared.taskchain.enums.TaskType;
import java.lang.annotation.*;

/**
 * 节点还需由接入方声明为 Spring Bean；领域契约不依赖 Spring。
 */
@Documented
@Inherited
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.TYPE)
public @interface TaskNode {
    /**
     * 节点标识，同一任务组内唯一。
     *
     * @return 任务组内唯一的节点标识
     */
    String nodeId();

    /**
     * 面向阅读的节点名称，留空时使用 nodeId。
     *
     * @return 节点展示名称；空白值由注册过程回退为标识
     */
    String nodeName() default "";

    /**
     * 节点职责、输入要求与产出说明，不参与执行决策。
     *
     * @return 节点用途说明
     */
    String description() default "";

    /**
     * 所属任务组。
     *
     * @return 节点所属任务组标识
     */
    String group();
    /**
     * 所属执行阶段，需要显式指定。
     *
     * @return 节点所属处理阶段
     */
    ProcessPhase phase();
    /**
     * 阶段内的排序值；并行模式下不表示节点之间存在依赖。
     *
     * @return 排序值；数值越小越先执行
     */
    int order() default 0;
    /**
     * 决定使用 CPU 还是 IO 工作线程池，需要显式指定。
     *
     * @return 决定工作线程池的 CPU 或 IO 任务类型
     */
    TaskType taskType();
    /**
     * 必需节点执行失败会阻断链路，可选节点失败仅记录诊断。
     *
     * @return 该业务判断是否成立
     */
    boolean required() default true;
}

package com.dianping.shared.taskchain.enums;

/**
 * 阶段内部节点的执行方式。
 */
public enum ExecutionMode {
    /**
     * 阶段内逐个执行，后续节点可读取已接受的前序结果。
     */
    SERIAL,
    /**
     * 阶段内并行执行，各节点读取同一初始快照。
     */
    PARALLEL }

package com.dianping.shared.taskchain.enums;

/**
 * 节点执行诊断状态，不等同于页面业务数据是否为空。
 */
public enum NodeExecutionStatus {
    /**
     * 节点成功完成。
     */
    SUCCESS,
    /**
     * 节点执行失败。
     */
    FAILED,
    /**
     * 节点在阶段预算内未完成。
     */
    TIMED_OUT,
    /**
     * 节点尚未执行，链路已经停止推进。
     */
    NOT_EXECUTED,
    /**
     * 节点已投递但因链路提前结束而不再接收结果。
     */
    ABANDONED
}

package com.dianping.shared.taskchain.enums;

/**
 * 任务链支持的固定处理阶段，调用方只配置所需阶段。
 */
public enum ProcessPhase {
    /**
     * 业务执行前的校验阶段。
     */
    PRE_VALIDATION,
    /**
     * 正式处理前的准备阶段。
     */
    PRE_PROCESSING,
    /**
     * 业务事实读取与处理阶段。
     */
    DATA_PROCESSING,
    /**
     * 需要持久化写入的业务阶段。
     */
    DATA_INSERTION,
    /**
     * 组装与衍生信息生成阶段。
     */
    POST_PROCESSING
}

package com.dianping.shared.taskchain.enums;

/**
 * 节点任务类型，用于 CPU 与 IO 线程池路由。
 */
public enum TaskType {
    /**
     * CPU 密集任务，使用 CPU 线程池。
     */
    CPU_BOUND,
    /**
     * IO 密集任务，使用 IO 线程池。
     */
    IO_BOUND
}

