 */
public record NodeExecutionResult(String nodeId, String nodeName, String group, ProcessPhase phase,
                                  boolean required, NodeExecutionStatus status, Throwable cause) { }

package com.dianping.shared.taskchain.model;

import com.dianping.shared.taskchain.enums.ExecutionMode;
import com.dianping.shared.taskchain.enums.ProcessPhase;
import java.time.Duration;
import java.util.Objects;

/**
 * 一个阶段的执行方式与共享超时预算，构造时拒绝无效配置。
 *
 * @param phase 节点所属的处理阶段
 * @param mode 阶段内串行或并行执行方式
 * @param timeout 整个阶段共享的超时预算
 */
public record PhaseConfig(ProcessPhase phase, ExecutionMode mode, Duration timeout) {
    /**
     * 创建并校验PhaseConfig，拒绝不满足业务约束的数据。
     *
     * @param phase 节点所属的处理阶段
     * @param mode 阶段内串行或并行执行方式
     * @param timeout 整个阶段共享的超时预算
     * @throws IllegalArgumentException 阶段预算不是正数或超出纳秒计时范围
     * @throws NullPointerException 阶段、执行方式或预算为空
     */
    public PhaseConfig {
        Objects.requireNonNull(phase, "phase 不得为空");
        Objects.requireNonNull(mode, "mode 不得为空");
        Objects.requireNonNull(timeout, "timeout 不得为空");
        if (timeout.isNegative() || timeout.isZero()) throw new IllegalArgumentException("阶段预算必须为正数");
        try { timeout.toNanos(); }
        catch (ArithmeticException error) { throw new IllegalArgumentException("阶段预算超出纳秒计时范围", error); }
    }
}

package com.dianping.shared.taskchain.model;

import com.dianping.shared.taskchain.enums.ProcessPhase;
import java.util.List;

/**
 * 当前业务的数据传输模型。
 *
 * @param phase 节点所属的处理阶段
 * @param canContinue 本阶段结束后是否允许继续后续阶段
 * @param cause 失败原因
 * @param nodeResults 本阶段各节点的有序诊断报告
 */
public record PhaseExecutionResult(ProcessPhase phase, boolean canContinue,
                                   Throwable cause, List<NodeExecutionResult> nodeResults) {
    /**
     * 创建 PhaseExecutionResult，初始化所需依赖及实例状态。
     *
     * @param phase 节点所属的处理阶段
     * @param canContinue 本阶段结束后是否允许继续后续阶段
     * @param cause 失败原因
     * @param nodeResults 本阶段各节点的有序诊断报告
     */
    public PhaseExecutionResult {
        nodeResults = List.copyOf(nodeResults);
    }
}

package com.dianping.shared.taskchain.model;

import java.util.*;

/**
 * 每次链路调用独立创建；节点仅通过上下文提交结果。
 *  引擎拥有的属性映射与报告集合为只读快照；输入、输出及属性值保留实际类型并遵守业务只读协议。
 *
 * @param <I> 链路输入类型
 * @param <O> 链路输出类型
 */
public class TaskContext<I, O> {
    /**
     * 链路输入；节点共享引用并按只读约定访问。
     */
    private final I input;
    //true表示节点上下文，false表示主上下文
    /**
     * 是否为节点视图。
     */
    private final boolean nodeView;
    //主上下文是否已经被领取执行，防止重复启动
    /**
     * 根上下文是否已领取执行权限，用于禁止复用。
     */
    private boolean claimed;
    //上下文是否已经被封存，封存后禁止写入
    /**
     * 上下文是否封存；封存后拒绝写入。
     */
    private boolean sealed;
    //节点工厂不得将同一个子上下文分配给多个任务
    /**
     * 节点视图是否已经交付给处理器，防止重复分配。
     */
    private boolean issued;
    //身份标记，判断一个子上下文是否属于当前主上下文
    /**
     * 同一次链路执行共享的身份标记。
     */
    private final Object owner;
    /**
     * 节点可见或准备提交的数据快照。
     */
    private Snapshot<O> snapshot;
    //预置数据
    /**
     * 尚未提交的属性写入或节点写集。
     */
    private final Map<String, Object> writes = new LinkedHashMap<>();
    /**
     * 本次写集要求删除的属性名。
     */
    private final Set<String> removals = new LinkedHashSet<>();
    /**
     * 当前节点或当前阶段是否显式写入输出。
     */
    private boolean outputWritten;
    /**
     * 尚未提交的节点输出。
     */
    private O localOutput;


    /**
     * 整条链路是否成功。
     */
    private boolean success;
    /**
     * 导致失败的异常；没有异常时为 {@code null}。
     */
    private Throwable error;
    /**
     * 链路结束后公布的阶段诊断报告。
     */
    private List<PhaseExecutionResult> phaseResults = List.of();

    /**
     * 创建本次请求专用的根上下文，初始快照为空。
     *
     * @param input 链路输入；节点共享引用并按只读约定访问
     */
    public TaskContext(I input) {
        this(input, new Snapshot<>(Map.of(), null, false), false, new Object());
    }

    /**
     * 子类创建节点上下文时调用；沿用本次请求身份与输入，使用引擎提供的可见快照。
     *
     * @param parent 创建当前节点视图的父上下文
     * @param snapshot 节点可见或准备提交的数据快照
     */
    protected TaskContext(TaskContext<I, O> parent, Snapshot<O> snapshot) {
        this(Objects.requireNonNull(parent, "父上下文不得为空").input,
                Objects.requireNonNull(snapshot, "节点快照不得为空"), true, parent.owner);
    }

    /**
     * 子类覆盖此工厂，返回同类型的新节点上下文；只负责创建对象，不执行查询等业务操作。
     *  业务属性 getter/setter 应委托 getAttribute/setAttribute，不能另存一份可变执行结果。
     *
     * @param snapshot 节点可见或准备提交的数据快照
     * @return 与根上下文具有相同业务类型的全新节点视图
     */
    protected TaskContext<I, O> createNodeContext(Snapshot<O> snapshot) {
        return new TaskContext<>(this, snapshot);
    }

    /**
     * 初始化输入、可见快照及节点身份，供根上下文和节点视图共用。
     *
     * @param input 链路输入；节点共享引用并按只读约定访问
     * @param snapshot 节点可见或准备提交的数据快照
     * @param nodeView 是否为节点视图
     * @param owner 同一次链路执行共享的身份标记
     */
    private TaskContext(I input, Snapshot<O> snapshot, boolean nodeView, Object owner) {
        this.input = input;
        this.snapshot = snapshot;
        this.nodeView = nodeView;
        this.owner = owner;
    }

    /**
     * 读取链路输入；返回的业务对象按只读约定使用。
     *
     * @return 本次链路的原始输入引用
     */
    public final I getInput() {
        return input;
    }
    /**
     * 读取当前快照与本地写集合成后的属性。
     *
     * @param key 上下文属性名或区域名称
     * @return 当前视图可见的业务值；尚未提供时为 {@code null}
     */
    public final synchronized Object getAttribute(String key) {
        return getAttributes().get(key);
    }
    /**
     * 生成当前视图的只读属性容器；不深复制其中的业务对象。
     *
     * @return 叠加当前写集后的只读属性映射
     */
    public final synchronized Map<String, Object> getAttributes() {
        var result = new LinkedHashMap<>(snapshot.attributes());
        removals.forEach(result::remove);
        result.putAll(writes);
        return Collections.unmodifiableMap(result);
    }

    /**
     * 将属性写入当前视图的本地写集；不会直接修改其他节点的可见快照。
     *
     * @param key 上下文属性名或区域名称
     * @param value 待读取或转换的值
     * @throws IllegalStateException 当前视图已封存，或根上下文已领取执行权限
     */
    public final synchronized void setAttribute(String key, Object value) {
        ensureWritable();
        Objects.requireNonNull(key, "属性 key 不得为空");
        writes.put(key, value);
        removals.remove(key);
    }
    /**
     * 记录属性删除，并清除该属性尚未提交的本地写入。
     *
     * @param key 上下文属性名或区域名称
     * @throws IllegalStateException 当前视图已封存，或根上下文已领取执行权限
     */
    public final synchronized void removeAttribute(String key) {
        ensureWritable();
        Objects.requireNonNull(key, "属性 key 不得为空");
        writes.remove(key);
        removals.add(key);
    }
    /**
     * 显式写入当前视图的输出槽位，包括写入空值。
     *
     * @param output 业务输出；允许显式写入 {@code null}
     * @throws IllegalStateException 当前视图已封存，或根上下文已领取执行权限
     */
    public final synchronized void setOutput(O output) {
        ensureWritable();
        localOutput = output;
        outputWritten = true;
    }
    /**
     * 读取当前视图可见的输出，优先使用本地显式写入值。
     *
     * @return 当前视图的业务输出；未设置或显式设空时均可能为 null，二者通过 hasOutput 区分
     */
    public final synchronized O getOutput() { return outputWritten ? localOutput : snapshot.output(); }
    /**
     * 判断输出是否曾被显式设置，区分未设置与显式设置为空。
     *
     * @return 输出是否曾被显式设置
     */
    public final synchronized boolean hasOutput() { return outputWritten || snapshot.outputSet(); }
    /**
     * 读取引擎封存的整条链路执行状态。
     *
     * @return 链路是否成功
     */
    public final synchronized boolean isSuccess() { return success; }
    /**
     * 读取使链路终止的首个阻断性异常。
     *
     * @return 首个阻断异常；没有异常时为 {@code null}
     */
    public final synchronized Throwable getError() { return error; }
    /**
     * 读取引擎封存的阶段执行报告。
     *
     * @return 按阶段执行顺序保存的只读报告列表
     */
    public final synchronized List<PhaseExecutionResult> getPhaseResults() { return phaseResults; }
    /**
     * 按阶段顺序展开全部节点诊断报告。
     *
     * @return 按阶段顺序展开的只读节点报告列表
     */
    public final synchronized List<NodeExecutionResult> getNodeResults() {
        return phaseResults.stream().flatMap(phase -> phase.nodeResults().stream()).toList();
    }

    //只有节点上下文可以标记自己失败，必需节点失败导致链路失败，可选节点失败保留诊断信息
    /**
     * 标记当前节点自身失败；必需或可选节点的影响由引擎统一判断。
     *
     * @param cause 失败原因
     * @throws IllegalStateException 根上下文试图标记节点失败，或当前节点已经封存
     */
    public final synchronized void fail(Throwable cause) {
        ensureWritable();
        if (!nodeView) throw new IllegalStateException("仅节点可以标记自身失败");
        if (error == null) error = Objects.requireNonNull(cause, "失败原因不得为空");
    }

    //确认上下文是否允许修改
    /**
     * 检查上下文是否允许写入，封存后的视图与已启动的根上下文均拒绝外部修改。
     *
     * @throws IllegalStateException 当前视图已封存，或根上下文已领取执行权限
     */
    private void ensureWritable() {
        //1.任何上下文被封存后都不得修改
        //2.主上下文开始执行后不允许修改，只能由引擎处理，没开始执行时调用方可以预置数据
        if (sealed || (!nodeView && claimed)) throw new IllegalStateException("上下文已进入执行或完成状态");
    }

    /**
     * 只有根上下文可领取一次协调权限；节点拿不到此权限。
     *
     * @return 只交给引擎使用的一次性执行协调权限
     * @throws IllegalStateException 上下文为节点视图，或根上下文已经开始过执行
     */
    public final synchronized Execution<I, O> beginExecution() {
        if (nodeView || claimed) {
            throw new IllegalStateException("上下文不能复用或由节点启动链路");
        }
        claimed = true;
        //用预置数据建立快照
        snapshot = snapshot.apply(new WriteSet<>(writes, removals, outputWritten, localOutput, null));
        writes.clear();
        removals.clear();
        outputWritten = false;
        return new Execution<>(this);
    }

    /**
     * 任务链在某个时刻已经积累的数据快照
     *  @param outputSet 标记是否显式设置过输出
     *
     * @param <O> 链路输出类型
     * @param attributes 只读属性映射；属性值遵守业务只读约定
     * @param output 业务输出；允许显式写入 {@code null}
     */
    public record Snapshot<O>(Map<String, Object> attributes, O output, boolean outputSet) {
        /**
         * 复制容器建立只读视图，业务对象本身仍按只读约定访问。
         *
         * @param attributes 只读属性映射；属性值遵守业务只读约定
         * @param output 业务输出；允许显式写入 {@code null}
         * @param outputSet 快照是否曾显式设置输出
         */
        public Snapshot {
            //创建一个只读的map，禁止调用put,remove等方法修改，但是如果val是可变数据类型就还能修改，所以统一约定遵守业务对象的只读规则
            attributes = Collections.unmodifiableMap(new LinkedHashMap<>(attributes));
        }
        //apply方法接收一个增量修改然后创建新的快照
        /**
         * 应用节点写集生成新快照，先删除属性再合并写入。
         *
         * @param delta 需要应用到旧快照上的节点写集
         * @return 合并删除、属性写入与输出更新后的新快照，原快照保持不变
         */
        public Snapshot<O> apply(WriteSet<O> delta) {
            var merged = new LinkedHashMap<>(attributes);
            //应用删除
            delta.removals().forEach(merged::remove);
            //应用写入
            merged.putAll(delta.attributes());
            //生成新快照
            return new Snapshot<>(merged, delta.outputWritten() ? delta.output() : output,
                    outputSet || delta.outputWritten());
        }
    }
    /**
     * 保存节点做了哪些修改
     *  @param attributes 属性
     *  @param removals 要删除的key
     *  @param outputWritten 标记，该节点是否显式设置过output
     *
     * @param <O> 链路输出类型
     * @param output 业务输出；允许显式写入 {@code null}
     * @param failure 节点失败原因；成功时为 {@code null}
     */
    public record WriteSet<O>(Map<String, Object> attributes, Set<String> removals,
                              boolean outputWritten, O output, Throwable failure) {
        /**
         * 复制容器建立只读视图，业务对象本身仍按只读约定访问。
         *
         * @param attributes 本节点待提交的属性写入映射；构造时复制容器
         * @param removals 本次写集要求删除的属性名
         * @param outputWritten 当前节点或当前阶段是否显式写入输出
         * @param output 业务输出；允许显式写入 {@code null}
         * @param failure 节点失败原因；成功时为 {@code null}
         */
        public WriteSet {
            attributes = Collections.unmodifiableMap(new LinkedHashMap<>(attributes));
            //记录要删除的键
            removals = Set.copyOf(removals);
        }
    }

    //为引擎提供操作入口，负责创建节点上下文、收集修改、提交数据、确定链路结果
    /**
     * 仅由引擎持有的协调权限，负责创建节点视图、接受写集及封存报告。
     *
     * @param <I> 链路输入类型
     * @param <O> 链路输出类型
     */
    public static final class Execution<I, O> {
        //绑定主上下文
        /**
         * 本次执行绑定的根上下文。
         */
        private final TaskContext<I, O> root;
        /**
         * 将协调权限绑定到唯一根上下文，供引擎管理本次执行。
         *
         * @param root 本次执行绑定的根上下文
         */
        private Execution(TaskContext<I, O> root) { this.root = root; }

        //获取主上下文当前已提交的数据
        /**
         * 读取主上下文当前已经提交的数据快照。
         *
         * @return 主上下文当前已提交的只读容器快照
         */
        public Snapshot<O> snapshot() { synchronized (root) { return root.snapshot; } }

        //为节点创建独立子上下文
        /**
         * 创建并检查属于本次执行的全新节点上下文，拒绝跨请求引用或重复分配。
         *
         * @param snapshot 节点可见或准备提交的数据快照
         * @return 与根上下文具有相同业务类型的全新节点视图
         * @throws IllegalStateException 根上下文已结束，或节点工厂未遵守同类型全新视图约定
         */
        public TaskContext<I, O> nodeContext(Snapshot<O> snapshot) {
            synchronized (root) {
                if (root.sealed) throw new IllegalStateException("链路已经结束");
                var node = root.createNodeContext(Objects.requireNonNull(snapshot, "节点快照不得为空"));
                if (node == null || node.getClass() != root.getClass()) {
                    throw new IllegalStateException("节点上下文必须与主上下文类型一致，请在子类覆盖 createNodeContext");
                }
                synchronized (node) {
                    if (!node.nodeView || node.owner != root.owner || node.input != root.input
                            || node.snapshot != snapshot || node.issued || node.claimed || node.sealed
                            || !node.writes.isEmpty() || !node.removals.isEmpty() || node.outputWritten || node.error != null) {
                        throw new IllegalStateException("节点工厂必须通过父上下文与当前快照创建本次执行的全新节点上下文");
                    }
                    node.issued = true;
                }
                return node;
            }
        }

        //收集节点结果
        /**
         * 封存节点视图并提取写集；提取结果是否接受由阶段引擎决定。
         *
         * @param node 任务节点或本次执行创建的节点上下文
         * @return 封存后的节点增量及显式失败原因
         * @throws IllegalArgumentException 传入的视图不是本次执行所属的节点上下文
         */
        public WriteSet<O> finishNode(TaskContext<I, O> node) {
            synchronized (node) {
                if (!node.nodeView || node.owner != root.owner) throw new IllegalArgumentException("不是本次执行的节点上下文");
                node.sealed = true;
                return new WriteSet<>(node.writes, node.removals, node.outputWritten, node.localOutput, node.error);
            }
        }

        //提交阶段通过后的快照
        /**
         * 将本阶段已经接受的快照提交到根上下文。
         *
         * @param snapshot 节点可见或准备提交的数据快照
         * @throws IllegalStateException 根上下文已经结束
         */
        public void commit(Snapshot<O> snapshot) {
            synchronized (root) {
                if (root.sealed) throw new IllegalStateException("链路已经结束");
                root.snapshot = snapshot;
            }
        }

        //确认整条链路的最终状态
        /**
         * 写入最终链路状态及只读报告集合，并封存根上下文。
         *
         * @param success 整条链路是否成功
         * @param error 导致失败的异常；没有异常时为 {@code null}
         * @param reports 按阶段或节点顺序保存的执行报告
         * @throws IllegalStateException 根上下文已经结束
         */
        public void finish(boolean success, Throwable error, List<PhaseExecutionResult> reports) {
            synchronized (root) {
                if (root.sealed) throw new IllegalStateException("链路已经结束");
                root.success = success;
                root.error = error;
                root.phaseResults = List.copyOf(reports);
                root.sealed = true;
            }
        }
    }
}

package com.dianping.shared.taskchain.model;

/**
 * 业务节点的执行契约，业务结果经上下文写集提交。
 *
 * @param <I> 链路输入类型
 * @param <O> 链路输出类型
 */
@FunctionalInterface
public interface TaskNodeHandler<I, O> {
    /**
     * 执行节点业务，读取可见上下文并通过属性或输出写集提交结果。
     *
     * @param context 当前调用独立使用的任务上下文
     * @throws Exception 节点业务执行失败，由引擎记录并决定是否阻断链路
     */
    void execute(TaskContext<I, O> context) throws Exception;
}

package com.dianping.shared.taskchain.model;

import com.dianping.shared.taskchain.enums.ProcessPhase;
import com.dianping.shared.taskchain.enums.TaskType;
import java.util.Objects;

/**
 * 节点处理器与元数据的绑定；名称用于展示，描述用于说明。
 *
 * @param <I> 链路输入类型
 * @param <O> 链路输出类型
 * @param nodeId 任务组内唯一的节点标识
 * @param nodeName 节点展示名称；空白时回退为节点标识
 * @param description 说明文本
 * @param group 任务组标识
 * @param phase 节点所属的处理阶段
 * @param order 阶段内排序值；数值越小越先执行
 * @param taskType 任务类型，决定投递到 CPU 池还是 IO 池
 * @param required 是否为失败后阻断链路的必需节点
 * @param handler 实际执行节点业务的处理器
 */
public record TaskNodeHolder<I, O>(String nodeId, String nodeName, String description,
                                   String group, ProcessPhase phase, int order,
                                   TaskType taskType, boolean required, TaskNodeHandler<I, O> handler) {
    /**
     * 手动注册时可省略展示元数据。
     *
     * @param nodeId 任务组内唯一的节点标识
     * @param group 任务组标识
     * @param phase 节点所属的处理阶段
     * @param order 阶段内排序值；数值越小越先执行
     * @param taskType 任务类型，决定投递到 CPU 池还是 IO 池
     * @param required 是否为失败后阻断链路的必需节点
     * @param handler 实际执行节点业务的处理器
     */
    public TaskNodeHolder(String nodeId, String group, ProcessPhase phase, int order,
                          TaskType taskType, boolean required, TaskNodeHandler<I, O> handler) {
        this(nodeId, "", "", group, phase, order, taskType, required, handler);
    }

    /**
     * 创建并校验TaskNodeHolder，拒绝不满足业务约束的数据。
     *
     * @param nodeId 任务组内唯一的节点标识
     * @param nodeName 节点展示名称；空白时回退为节点标识
     * @param description 说明文本
     * @param group 任务组标识
     * @param phase 节点所属的处理阶段
     * @param order 阶段内排序值；数值越小越先执行
     * @param taskType 任务类型，决定投递到 CPU 池还是 IO 池
     * @param required 是否为失败后阻断链路的必需节点
     * @param handler 实际执行节点业务的处理器
     */
    public TaskNodeHolder {
        if (nodeId == null || nodeId.isBlank() || group == null || group.isBlank()) {
            throw new IllegalArgumentException("节点 nodeId 和 group 不得为空白");
        }
        nodeName = nodeName == null || nodeName.isBlank() ? nodeId : nodeName;
        description = Objects.requireNonNullElse(description, "");
        Objects.requireNonNull(phase, "phase 不得为空");
        Objects.requireNonNull(taskType, "taskType 不得为空");
        Objects.requireNonNull(handler, "handler 不得为空");
    }
}

package com.dianping.shared.taskchain.model;

import com.dianping.shared.taskchain.enums.ProcessPhase;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * 任务节点注册表，启动时按任务组校验唯一性并排序冻结，运行时按阶段只读查询。
 */
public final class TaskNodeRegistry {
    /**
     * 按任务组组织的节点集合。
     */
    private final Map<String, List<TaskNodeHolder<?, ?>>> groups = new HashMap<>();
    //是否已经结束注册，进入只读使用状态
    /**
     * 注册表是否已排序并进入只读状态。
     */
    private boolean frozen;

    /**
     * 校验并注册节点；同组标识必须唯一，冻结后不再允许注册。
     *
     * @param holder 待注册的处理器及节点元数据
     * @throws IllegalStateException 注册表已经冻结
     * @throws IllegalArgumentException 同组节点标识重复
     */
    public synchronized void register(TaskNodeHolder<?, ?> holder) {
        if (frozen) throw new IllegalStateException("节点注册表已经冻结");

        Objects.requireNonNull(holder, "节点不得为空");

        var nodes = groups.computeIfAbsent(holder.group(), ignored -> new ArrayList<>());

        if (nodes.stream().anyMatch(node -> node.nodeId().equals(holder.nodeId()))) {
            throw new IllegalArgumentException("任务组内节点 nodeId 重复：" + holder.group() + "/" + holder.nodeId());
        }
        nodes.add(holder);
    }

    //排序并结束注册,先按order排，再按nodeId排
    /**
     * 按排序值和节点标识排序，并将注册表切换为只读状态。
     */
    public synchronized void freeze() {
        groups.replaceAll((group, nodes) -> nodes.stream()
                .sorted(Comparator.<TaskNodeHolder<?, ?>>comparingInt(TaskNodeHolder::order)
                        .thenComparing(TaskNodeHolder::nodeId)).toList());
        frozen = true;
    }

    /**
     * 检查节点注册表是否已经冻结。
     *
     * @return 注册表是否已冻结
     */
    public synchronized boolean isFrozen() {
        return frozen;
    }

    //按组和阶段取出节点
    /**
     * 按任务组和阶段取得排序后的节点列表。
     *
     * @param group 任务组标识
     * @param phase 节点所属的处理阶段
     * @return 指定任务组和阶段的只读有序节点列表
     */
    public synchronized List<TaskNodeHolder<?, ?>> nodes(String group, ProcessPhase phase) {
        if (!frozen) throw new IllegalStateException("执行前必须冻结节点注册表");

        Objects.requireNonNull(phase, "阶段不得为空");

        var nodes = groups.get(group);
        if (nodes == null) throw new IllegalArgumentException("未知任务组：" + group);
        return nodes.stream().filter(node -> node.phase() == phase).toList();
    }
}

package com.dianping.shared.taskchain.service;

import com.dianping.shared.taskchain.enums.ExecutionMode;
import com.dianping.shared.taskchain.enums.NodeExecutionStatus;
import com.dianping.shared.taskchain.model.*;
import java.util.*;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.Future;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/**
 * 阶段执行引擎
 *  <p>
 *  负责阶段内部的节点编排，根据 {@link PhaseConfig} 阶段配置控制执行方式和阶段总超时：
 *  </p>
 *  <ul>
 *     <li>串行执行：按节点顺序逐个执行，后续节点可以读取前面成功节点的结果</li>
 *     <li>并行执行：各节点读取阶段开始时的同一快照，通过进程内完成通知队列收集结果</li>
 *     <li>失败处理：必需节点失败后尽快结束等待；可选节点失败仅保留诊断，丢弃其局部写入</li>
 *     <li>超时控制：所有节点共享阶段总预算；到期时若仍有必需节点未完成，则阶段失败，仅剩可选节点时允许继续</li>
 *     <li>结果合并：检查成功并行节点的同名属性（包括删除）和 output 写入冲突，阶段允许继续时才统一提交结果</li>
 *     <li>提前结束：尽力取消未完成任务，不再接受迟到结果；取消不保证底层任务立即停止</li>
 *  </ul>
 *  <p>
 *  节点投递由 {@link TaskDispatcher} 负责，阶段结果通过 {@link PhaseExecutionResult} 返回给 {@link TaskChainEngine}。
 *  阶段失败仅丢弃本阶段的上下文写入，不回滚前序阶段结果或节点产生的外部副作用。
 *  </p>
 */
public final class PhaseExecutionEngine {
    /**
     * 任务节点投递器。
     */
    private final TaskDispatcher dispatcher;
    /**
     * 创建 PhaseExecutionEngine，初始化所需依赖及实例状态。
     *
     * @param dispatcher 任务节点投递器
     */
    public PhaseExecutionEngine(TaskDispatcher dispatcher) {
        this.dispatcher = Objects.requireNonNull(dispatcher, "调度器不得为空");
    }

    /**
     * 执行一个阶段；节点共享阶段总预算，成功结果在阶段收尾时统一决定是否提交。
     *
     * @param <I> 链路输入类型
     * @param <O> 链路输出类型
     * @param config 当前阶段配置
     * @param nodes 本阶段按顺序排列的任务节点
     * @param execution 引擎持有的本次链路协调权限
     * @return 当前阶段能否继续及各节点诊断报告
     */
    public <I, O> PhaseExecutionResult execute(PhaseConfig config, List<TaskNodeHolder<?, ?>> nodes,
                                              TaskContext.Execution<I, O> execution) {
        return new StageRun<>(config, List.copyOf(nodes), execution).run();
    }

    /**
     * 单次阶段执行状态，集中维护共享预算、完成队列、合并冲突与节点报告。
     *
     * @param <I> 链路输入类型
     * @param <O> 链路输出类型
     */
    private final class StageRun<I, O> {
        /**
         * 当前阶段配置。
         */
        private final PhaseConfig config;
        /**
         * 本阶段按顺序排列的任务节点。
         */
        private final List<TaskNodeHolder<?, ?>> nodes;
        /**
         * 引擎持有的本次链路协调权限。
         */
        private final TaskContext.Execution<I, O> execution;
        /**
         * 阶段起始快照或本次查询的店铺基本资料。
         */
        private final TaskContext.Snapshot<O> base;
        /**
         * 累积已接受写集后的待提交快照。
         */
        private TaskContext.Snapshot<O> working;
        /**
         * 阶段开始时的单调时钟纳秒值。
         */
        private final long started = System.nanoTime();
        /**
         * 本阶段允许消耗的总纳秒数。
         */
        private final long budget;
        //完成通知队列
        /**
         * 工作线程向协调线程发送完成通知的队列。
         */
        private final BlockingQueue<TaskDispatcher.Outcome<O>> completionQueue = new LinkedBlockingQueue<>();
        /**
         * 已投递任务的句柄，用于尽力取消。
         */
        private final List<Future<?>> futures = new ArrayList<>();
        /**
         * 按阶段或节点顺序保存的执行报告。
         */
        private final NodeExecutionResult[] reports;
        /**
         * 并行阶段成功节点已写入或删除的属性名，用于检测冲突。
         */
        private final Set<String> touched = new HashSet<>();
        /**
         * 当前节点或当前阶段是否显式写入输出。
         */
        private boolean outputWritten;
        /**
         * 已接收完成通知的节点数量。
         */
        private int finished;
        /**
         * 当前首先观察到的阻断性错误。
         */
        private Throwable fatal;
        /**
         * 阶段总预算是否已经耗尽。
         */
        private boolean expired;

        /**
         * 创建 StageRun，初始化所需依赖及实例状态。
         *
         * @param config 当前阶段配置
         * @param nodes 本阶段按顺序排列的任务节点
         * @param execution 引擎持有的本次链路协调权限
         */
        StageRun(PhaseConfig config, List<TaskNodeHolder<?, ?>> nodes, TaskContext.Execution<I, O> execution) {
            this.config = config;
            this.nodes = nodes;
            this.execution = execution;
            this.base = execution.snapshot();
            this.working = base;
            this.budget = config.timeout().toNanos();
            this.reports = new NodeExecutionResult[nodes.size()];
        }

        /**
         * 执行一次阶段运行，收集节点通知，决定是否提交结果并生成完整报告。
         *
         * @return 当前阶段能否继续及各节点诊断报告
         */
        PhaseExecutionResult run() {
            try {
                for (int i = 0; i < nodes.size() && fatal == null; i++) {
                    drainAvailable();
                    if (fatal != null) break;
                    if (remaining() <= 0) { expire(); break; }
                    futures.add(dispatcher.dispatch(i, nodes.get(i), execution,
                            config.mode() == ExecutionMode.PARALLEL ? base : working, completionQueue::add));
                    if (config.mode() == ExecutionMode.SERIAL) {
                        while (reports[i] == null && fatal == null && !expired) awaitCompletion();
                    }
                    if (expired) break;
                }
                while (finished < nodes.size() && fatal == null && !expired) awaitCompletion();
            } catch (InterruptedException error) {
                Thread.currentThread().interrupt();
                fatal = error;
            }
            for (int i = 0; i < nodes.size(); i++) {
                if (reports[i] == null) reports[i] = report(nodes.get(i),
                        i < futures.size() ? NodeExecutionStatus.ABANDONED : NodeExecutionStatus.NOT_EXECUTED, null);
            }
            if (fatal != null || expired) futures.forEach(future -> future.cancel(true));
            if (fatal == null) execution.commit(working);
            return new PhaseExecutionResult(config.phase(), fatal == null, fatal, Arrays.asList(reports));
        }

        /**
         * 计算共享阶段总预算的剩余纳秒数。
         *
         * @return 剩余纳秒数；非正数表示阶段预算耗尽
         */
        private long remaining() { return budget - (System.nanoTime() - started); }

        /**
         * 在剩余阶段预算内等待并接收一个完成通知。
         *
         * @throws InterruptedException 协调线程等待节点完成时被中断
         */
        private void awaitCompletion() throws InterruptedException {
            long left = remaining();
            if (left <= 0) { expire(); return; }
            var outcome = completionQueue.poll(left, TimeUnit.NANOSECONDS);
            if (outcome == null) expire();
            else {
                accept(outcome);
                if (outcome.completedAt() - started > budget && fatal == null) expire();
            }
        }

        /**
         * 立即接收已经到达的完成通知，不额外等待。
         */
        private void drainAvailable() {
            TaskDispatcher.Outcome<O> outcome;
            while (fatal == null && (outcome = completionQueue.poll()) != null) accept(outcome);
        }

        /**
         * 接收预算内的节点结果，处理必需失败及并行写入冲突。
         *
         * @param outcome 待接收的节点完成通知
         */
        private void accept(TaskDispatcher.Outcome<O> outcome) {
            if (reports[outcome.index()] != null || outcome.completedAt() - started > budget) return;
            var node = nodes.get(outcome.index());
            reports[outcome.index()] = report(node, outcome.failure() == null
                    ? NodeExecutionStatus.SUCCESS : NodeExecutionStatus.FAILED, outcome.failure());
            finished++;
            if (outcome.failure() != null) {
                if (node.required()) fatal = outcome.failure();
                return;
            }
            if (config.mode() == ExecutionMode.PARALLEL) {
                var keys = new HashSet<>(outcome.writes().attributes().keySet());
                keys.addAll(outcome.writes().removals());
                if (keys.stream().anyMatch(touched::contains) || (outputWritten && outcome.writes().outputWritten())) {
                    fatal = new IllegalStateException("并行节点结果存在同名属性或 output 冲突：" + node.nodeId());
                    return;
                }
                touched.addAll(keys);
                outputWritten |= outcome.writes().outputWritten();
            }
            working = working.apply(outcome.writes());
        }

        /**
         * 结束阶段等待，保留截止前完成的结果并标记未完成节点超时。
         */
        private void expire() {
            // 截止前已投递的完成通知仍可接受，完成时间超过预算的结果永不回写。
            drainAvailable();
            if (fatal != null) return;
            expired = true;
            for (int i = 0; i < nodes.size(); i++) {
                if (reports[i] != null) continue;
                var timeout = new TimeoutException("阶段预算耗尽，节点未及时完成：" + nodes.get(i).nodeId());
                reports[i] = report(nodes.get(i), NodeExecutionStatus.TIMED_OUT, timeout);
                if (nodes.get(i).required() && fatal == null) fatal = timeout;
            }
        }
    }

    /**
     * 将节点元数据、执行状态与异常组合为诊断报告。
     *
     * @param node 任务节点或本次执行创建的节点上下文
     * @param status 业务或节点状态
     * @param error 导致失败的异常；没有异常时为 {@code null}
     * @return 包含节点标识、必需性、执行状态及失败原因的诊断报告
     */
    static NodeExecutionResult report(TaskNodeHolder<?, ?> node, NodeExecutionStatus status, Throwable error) {
        return new NodeExecutionResult(node.nodeId(), node.nodeName(), node.group(), node.phase(), node.required(), status, error);
    }
}

package com.dianping.shared.taskchain.service;

import com.dianping.shared.taskchain.enums.ExecutionMode;
import com.dianping.shared.taskchain.enums.NodeExecutionStatus;
import com.dianping.shared.taskchain.enums.ProcessPhase;
import com.dianping.shared.taskchain.model.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.Executor;

/**
 * 任务链入口，按调用方配置的顺序推进阶段，并封存链路结果及执行报告。
 * <ul>
 *   <li>{@link #executeChain(String, TaskContext)}：按默认五阶段串行执行。</li>
 *   <li>{@link #executePhaseChain(String, TaskContext, List)}：自定义阶段顺序与阶段内执行方式。</li>
 * </ul>
 */
public final class TaskChainEngine {
    /**
     * 按任务组与阶段组织的节点注册表。
     */
    private final TaskNodeRegistry registry;
    /**
     * 负责单阶段节点执行与结果合并的引擎。
     */
    private final PhaseExecutionEngine phaseEngine;
    /**
     * 五个固定阶段的默认串行配置。
     */
    private final List<PhaseConfig> defaultPhases;

    /**
     * 创建 TaskChainEngine，初始化所需依赖及实例状态。
     *
     * @param registry 按任务组与阶段组织的节点注册表
     * @param cpuExecutor CPU 密集任务执行器
     * @param ioExecutor IO 密集任务执行器
     * @param defaultPhaseTimeout 默认单阶段执行预算
     */
    public TaskChainEngine(TaskNodeRegistry registry, Executor cpuExecutor,
                           Executor ioExecutor, Duration defaultPhaseTimeout) {
        this.registry = Objects.requireNonNull(registry, "注册表不得为空");
        this.phaseEngine = new PhaseExecutionEngine(new TaskDispatcher(cpuExecutor, ioExecutor));
        this.defaultPhases = Arrays.stream(ProcessPhase.values())
                .map(phase -> new PhaseConfig(phase, ExecutionMode.SERIAL, defaultPhaseTimeout)).toList();
    }

    /**
     * 按默认五阶段串行配置执行任务组，保留输入上下文的实际子类型。
     *
     * @param <I> 链路输入类型
     * @param <O> 链路输出类型
     * @param <C> 实际业务上下文类型
     * @param group 任务组标识
     * @param context 当前调用独立使用的任务上下文
     * @return 已封存执行状态与报告的原始业务上下文
     * @throws IllegalArgumentException 任务组、阶段配置或节点选择不合法
     * @throws IllegalStateException 注册表尚未冻结，或上下文已被使用
     */
    public <I, O, C extends TaskContext<I, O>> C executeChain(String group, C context) {
        return executePhaseChain(group, context, defaultPhases);
    }

    /**
     * 按调用方给定的阶段顺序执行任务组，并将失败及诊断信息封存到上下文。
     *
     * @param <I> 链路输入类型
     * @param <O> 链路输出类型
     * @param <C> 实际业务上下文类型
     * @param group 任务组标识
     * @param context 当前调用独立使用的任务上下文
     * @param phaseConfigs 按执行顺序排列且阶段不重复的配置
     * @return 已封存执行状态与报告的原始业务上下文
     * @throws IllegalArgumentException 任务组、阶段配置或节点选择不合法
     * @throws IllegalStateException 注册表尚未冻结，或上下文已被使用
     */
    public <I, O, C extends TaskContext<I, O>> C executePhaseChain(String group, C context,
                                                    List<PhaseConfig> phaseConfigs) {
        //校验任务链配置
        Objects.requireNonNull(context, "上下文不得为空");
        if (group == null || group.isBlank()) throw new IllegalArgumentException("任务组不得为空白");
        if (phaseConfigs == null || phaseConfigs.isEmpty()) throw new IllegalArgumentException("阶段列表不得为空");
        //按执行顺序排列的阶段配置列表
        var phases = List.copyOf(phaseConfigs);
        //每个阶段对应的任务节点列表
        var selected = new ArrayList<List<TaskNodeHolder<?, ?>>>();
        var seen = EnumSet.noneOf(ProcessPhase.class);

        for (var phase : phases) {
            if (!seen.add(phase.phase())) throw new IllegalArgumentException("阶段不得重复：" + phase.phase());
            selected.add(registry.nodes(group, phase.phase()));
        }
        //校验通过之后领取本次上下文的执行权限，防止同一个上下文被复用
        var execution = context.beginExecution();
        //收集每个阶段的执行报告
        var reports = new ArrayList<PhaseExecutionResult>();
        //标志变量，标志是否已经出现阻断性错误
        Throwable fatal = null;
        //依次执行每个阶段
        for (int i = 0; i < phases.size(); i++) {
            //没有阻断错误就继续执行
            if (fatal == null) {
                var result = phaseEngine.execute(phases.get(i), selected.get(i), execution);
                reports.add(result);//记录报告
                if (!result.canContinue()) fatal = result.cause();//阶段无法继续时及时记录原因
            }//已经出现阻断错误，后续阶段不执行，只记录
            else {
                var skipped = selected.get(i).stream().map(node -> PhaseExecutionEngine.report(node,
                        NodeExecutionStatus.NOT_EXECUTED, null)).toList();
                reports.add(new PhaseExecutionResult(phases.get(i).phase(), false, null, skipped));
            }
        }
        execution.finish(fatal == null, fatal, reports);
        return context;
    }
}

package com.dianping.shared.taskchain.service;

import com.dianping.shared.taskchain.enums.TaskType;
import com.dianping.shared.taskchain.model.TaskContext;
import com.dianping.shared.taskchain.model.TaskNodeHandler;
import com.dianping.shared.taskchain.model.TaskNodeHolder;
import java.util.Objects;
import java.util.concurrent.Executor;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Future;
import java.util.concurrent.FutureTask;
import java.util.concurrent.RejectedExecutionException;
import java.util.function.Consumer;


/**
 * 节点投递器，隔离节点上下文并按 CPU 或 IO 类型路由线程池，通过完成通知交回写集。
 */
public final class TaskDispatcher {
    /**
     * CPU 密集任务执行器。
     */
    private final Executor cpuExecutor;
    /**
     * IO 密集任务执行器。
     */
    private final Executor ioExecutor;

    /**
     * 创建 TaskDispatcher，初始化所需依赖及实例状态。
     *
     * @param cpuExecutor CPU 密集任务执行器
     * @param ioExecutor IO 密集任务执行器
     */
    public TaskDispatcher(Executor cpuExecutor, Executor ioExecutor) {
        this.cpuExecutor = Objects.requireNonNull(cpuExecutor, "CPU 执行器不得为空");
        this.ioExecutor = Objects.requireNonNull(ioExecutor, "IO 执行器不得为空");
    }

    /**
     * 核心方法dispatch，如何路由任务节点
     *  @param index 节点在当前阶段列表中的下标
     *  @param node 任务节点
     *  @param execution 本次任务链的执行权限对象
     *  @param snapshot 这个节点允许的数据快照
     *  @param completed 调用方传入一个能接收{@code Outcome<O>}类型参数的规则，这里就是PhaseExecutionEngine传入的{@code completionQueue::add}
     *  @return  future，作为任务句柄，封装任务结果
     *  @param <I> 泛型  入参
     *  @param <O> 泛型  出参
     */
    @SuppressWarnings("unchecked")
    <I, O> Future<?> dispatch(int index, TaskNodeHolder<?, ?> node, TaskContext.Execution<I, O> execution,
                             TaskContext.Snapshot<O> snapshot, Consumer<Outcome<O>> completed) {
        //给节点创建独立的节点上下文
        TaskContext<I, O> local;
        try {
            local = execution.nodeContext(snapshot);
        } catch (RuntimeException error) {
            //上下文创建失败就转化成节点失败通知
            completed.accept(new Outcome<>(index, new TaskContext.WriteSet<>(java.util.Map.of(),
                    java.util.Set.of(), false, null, error), error, System.nanoTime()));
            return CompletableFuture.completedFuture(null);
        }
        //开始定义任务
        var task = new FutureTask<Void>(() -> {
            Throwable failure = null;
            try { ((TaskNodeHandler<I, O>) node.handler()).execute(local); }
            //节点兼容两种失败表达方式，一种是throw的异常，一种是context.fail(cause)在写集里记录异常
            catch (Throwable error) {
                failure = error;
            }
            //成功就封存节点上下文，提供写集
            var writes = execution.finishNode(local);
            if (failure == null) failure = writes.failure();
            //把结果写入完成通知队列
            completed.accept(new Outcome<>(index, writes, failure, System.nanoTime()));
            return null;
        });
        //根据任务类型路由到对应的线程池
        try { (node.taskType() == TaskType.CPU_BOUND ? cpuExecutor : ioExecutor).execute(task); }
        catch (RejectedExecutionException error) {
            task.cancel(false);
            completed.accept(new Outcome<>(index, execution.finishNode(local), error, System.nanoTime()));
        }
        return task;
    }

    /**
     * 记录节点的执行结果
     *  @param index 节点在当前阶段列表中的下标
     *  @param writes 节点产生的局部修改
     *  @param failure 节点的失败原因
     *  @param completedAt 节点完成时的单调时钟纳秒值
     *  @param <O> 泛型信息 出参
     */
    record Outcome<O>(int index, TaskContext.WriteSet<O> writes, Throwable failure, long completedAt) { }
}

package com.dianping.shopdetail.enums;

import java.util.Arrays;

/**
 * 稳定代码用于持久化，展示名称可独立调整。
 */
