package com.dianping.shopdetail.repository;

import com.dianping.shopdetail.exception.DuplicateRecommendDishException;
import com.dianping.shopdetail.model.RecommendDish;
import com.dianping.shopdetail.model.ShopPage;
import org.springframework.transaction.annotation.*;
import com.dianping.shopdetail.persistence.mapper.RecommendDishMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Repository;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Optional;
import java.util.Set;

/**
 * 实现RecommendDish仓储，负责数据库查询及持久化模型转换。
 */
@Repository
public class RecommendDishRepositoryImpl implements RecommendDishRepository {
    /**
     * 数据映射器。
     */
    private final RecommendDishMapper mapper;
    /**
     * 创建 RecommendDishRepositoryImpl，初始化所需依赖及实例状态。
     *
     * @param mapper 当前业务的 MyBatis 数据访问接口
     */
    public RecommendDishRepositoryImpl(RecommendDishMapper mapper) { this.mapper = mapper; }

    /**
     * 检查店铺记录是否存在。
     *
     * @param shopId 店铺标识
     * @return 店铺是否存在
     */
    @Override public boolean shopExists(Long shopId) { return mapper.shopExists(shopId); }
    /**
     * 锁定店铺行，串行化该店铺的业务写入。
     *
     * @param shopId 店铺标识
     * @return 店铺是否存在且已成功取得行锁
     */
    @Override public boolean lockShop(Long shopId) { return mapper.lockShop(shopId) != null; }
    /**
     * 按作者和提交标识查询已持久化内容，用于幂等处理。
     *
     * @param userId 服务端确认的用户标识
     * @param requestId 客户端生成的 UUID 提交标识，用于幂等校验
     * @return 相同用户及提交标识对应的持久化记录；不存在时为空
     */
    @Override public Optional<RecommendDish> findSubmission(Long userId, String requestId) {
        return Optional.ofNullable(mapper.findSubmission(userId, requestId)).map(this::toDomain);
    }
    /**
     * 按当前店铺与规范菜名查询已有推荐菜。
     *
     * @param shopId 店铺标识
     * @param name 名称
     * @return 店内同规范菜名的记录；不存在时为空
     */
    @Override public Optional<RecommendDish> findByName(Long shopId, String name) {
        return Optional.ofNullable(mapper.findByName(shopId, name.getBytes(StandardCharsets.UTF_8))).map(this::toDomain);
    }
    /**
     * 插入经过领域校验的业务记录，并返回生成标识。
     *
     * @param dish 推荐菜业务数据
     * @return 新记录标识
     */
    @Override public Long insert(RecommendDish dish) {
        var row = new com.dianping.shopdetail.persistence.dataobject.RecommendDish();
        row.setShopId(dish.shopId()); row.setUserId(dish.userId()); row.setRequestId(dish.requestId());
        row.setName(dish.name()); row.setNameKey(dish.name().getBytes(StandardCharsets.UTF_8));
        row.setCoverImage(dish.coverImage()); row.setRecommendCount(dish.recommendCount()); row.setCreateTime(dish.createTime());
        try { mapper.insert(row); return row.getId(); }
        catch (DuplicateKeyException error) { throw new DuplicateRecommendDishException(error); }
    }
    /**
     * 按店铺和菜品标识查询并加行锁，用于推荐关系与人数一致更新。
     *
     * @param shopId 店铺标识
     * @param dishId 菜品标识
     * @return 已加行锁的指定店内菜品；不存在时为空
     */
    @Override public Optional<RecommendDish> lockDish(Long shopId, Long dishId) {
        return Optional.ofNullable(mapper.lockDish(shopId, dishId)).map(this::toDomain);
    }
    /**
     * 按店铺和菜品标识查询推荐菜，避免跨店引用。
     *
     * @param shopId 店铺标识
     * @param dishId 菜品标识
     * @return 指定店内的菜品记录；不存在时为空
     */
    @Override public Optional<RecommendDish> findById(Long shopId, Long dishId) {
        return Optional.ofNullable(mapper.findById(shopId, dishId)).map(this::toDomain);
    }
    /**
     * 判断用户是否已推荐指定菜品。
     *
     * @param dishId 菜品标识
     * @param userId 服务端确认的用户标识
     * @return 当前用户是否已经推荐该菜品
     */
    @Override public boolean hasRecommendation(Long dishId, Long userId) { return mapper.hasRecommendation(dishId, userId); }
    /**
     * 插入用户与菜品的去重推荐关系。
     *
     * @param dishId 菜品标识
     * @param userId 服务端确认的用户标识
     */
    @Override public void insertRecommendation(Long dishId, Long userId) {
        if (mapper.insertRecommendation(dishId, userId) != 1) throw new IllegalStateException("推荐关系写入失败");
    }
    /**
     * 将菜品的不同用户推荐人数增加一。
     *
     * @param dishId 菜品标识
     */
    @Override public void incrementRecommendationCount(Long dishId) {
        if (mapper.incrementRecommendationCount(dishId) != 1) throw new IllegalStateException("推荐人数更新失败");
    }
    /**
     * 统计指定店铺的全部业务记录。
     *
     * @param shopId 店铺标识
     * @return 匹配记录数或十倍总体评分总和
     */
    @Override public long countByShopId(Long shopId) { return mapper.countByShopId(shopId); }
    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param shopId 店铺标识
     * @param offset 从 0 开始的记录偏移量
     * @param size 每页数量
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    @Override public List<RecommendDish> page(Long shopId, long offset, int size) {
        return mapper.page(shopId, offset, size).stream().map(this::toDomain).toList();
    }
    /**
     * 批量读取当前用户已推荐的菜品标识。
     *
     * @param userId 服务端确认的用户标识
     * @param dishIds 待检查的菜品标识集合
     * @return 当前用户在给定菜品集合中已推荐的标识
     */
    @Override public Set<Long> recommendedIds(Long userId, List<Long> dishIds) {
        return dishIds.isEmpty() ? Set.of() : Set.copyOf(mapper.recommendedIds(userId, dishIds));
    }
    /**
     * 将数据库记录映射为领域业务数据。
     *
     * @param row 数据库记录
     * @return 由持久化字段恢复的领域业务对象
     */
    private RecommendDish toDomain(com.dianping.shopdetail.persistence.dataobject.RecommendDish row) {
        return new RecommendDish(row.getId(), row.getShopId(), row.getUserId(), row.getRequestId(),
                row.getName(), row.getCoverImage(), row.getRecommendCount(), row.getCreateTime());
    }
    /**
     * 在同一读取快照内取得分页明细和总数。
     *
     * @param shopId 店铺标识
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    @Override
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopPage<RecommendDish> pageWithTotal(Long shopId, long current, int size) {
        return new ShopPage<>(page(shopId, Math.multiplyExact(current - 1, (long) size), size),
                countByShopId(shopId), current, size);
    }
}

package com.dianping.shopdetail.repository;

import com.dianping.shopdetail.enums.ReviewTag;
import com.dianping.shopdetail.model.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.*;

/**
 * 商详读取直接映射为领域数据，不调用遗留 Service 或请求线程身份。
 */
@Repository
public class ShopDetailRepositoryImpl implements ShopDetailRepository {
    /**
     * 关系数据库查询模板。
     */
    private final JdbcTemplate jdbc;
    /**
     * 博客点赞集合使用的 Redis 模板。
     */
    private final StringRedisTemplate redis;
    /**
     * 创建 ShopDetailRepositoryImpl，初始化所需依赖及实例状态。
     *
     * @param jdbc 关系数据库查询模板
     * @param redis 博客点赞集合使用的 Redis 模板
     */
    public ShopDetailRepositoryImpl(JdbcTemplate jdbc, StringRedisTemplate redis) {
        this.jdbc = jdbc; this.redis = redis;
    }
    /**
     * 基础店铺资料使用的数据库列集合。
     */
    private static final String BASE_COLUMNS = "id,name,type_id,images,area,address,x,y,avg_price,open_hours";
    /**
     * 基础资料的数据库行映射器。
     */
    private static final RowMapper<ShopBaseInfo> BASE = (r, n) -> new ShopBaseInfo(
            r.getLong("id"), r.getString("name"), r.getObject("type_id", Long.class),
            r.getString("images"), r.getString("area"), r.getString("address"),
            r.getObject("x", Double.class), r.getObject("y", Double.class),
            r.getObject("avg_price", Long.class), r.getString("open_hours"));

    /**
     * 读取店铺自身基础资料，不使用旧缓存中的评价统计。
     *
     * @param id 记录标识
     * @return 店铺基本资料；不存在时返回空 Optional
     */
    public Optional<ShopBaseInfo> findShop(Long id) {
        return jdbc.query("SELECT " + BASE_COLUMNS + " FROM tb_shop WHERE id=?", BASE, id).stream().findFirst();
    }
    /**
     * 读取当前店铺的探店笔记，并按显式传入的身份补齐点赞状态。
     *
     * @param shopId 店铺标识
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @param viewerId 当前浏览者标识；游客传入 {@code null}
     * @return 探店笔记及当前浏览者点赞状态的分页结果，包含总数与当前页记录
     */
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopPage<ShopVisitBlog> blogs(Long shopId, long current, int size, Long viewerId) {
        long total = jdbc.queryForObject("SELECT COUNT(*) FROM tb_blog WHERE shop_id=?", Long.class, shopId);
        List<ShopVisitBlog> rows = jdbc.query("""
                SELECT b.*,u.nick_name AS user_name,u.icon AS user_icon
                FROM tb_blog b LEFT JOIN tb_user u ON b.user_id=u.id
                WHERE b.shop_id=? ORDER BY b.liked DESC,b.create_time DESC,b.id DESC LIMIT ? OFFSET ?
                """, (r, n) -> {
            var blog = new ShopVisitBlog();
            blog.setId(r.getLong("id")); blog.setShopId(r.getLong("shop_id")); blog.setUserId(r.getLong("user_id"));
            blog.setUserName(Objects.requireNonNullElse(r.getString("user_name"), "用户"));
            blog.setUserIcon(r.getString("user_icon")); blog.setTitle(r.getString("title"));
            blog.setImages(r.getString("images"));
            String content = r.getString("content");
            blog.setContent(content == null ? "" : content.replaceAll("<[^>]*>", " ").substring(0,
                    Math.min(120, content.replaceAll("<[^>]*>", " ").length())));
            blog.setLiked(r.getInt("liked")); blog.setComments(r.getInt("comments"));
            blog.setCreateTime(time(r, "create_time")); blog.setUpdateTime(time(r, "update_time"));
            blog.setIsLike(false);
            return blog;
        }, shopId, size, Math.multiplyExact(current - 1, (long) size));
        if (viewerId != null && !rows.isEmpty()) {
            try {
                for (var row : rows)
                    row.setIsLike(redis.opsForSet().isMember(com.dianping.constant.RedisConstants.BLOG_LIKE_KEY + row.getId(), viewerId.toString()));
            } catch (RuntimeException error) {
                // 点赞状态不可用不隐藏公开博客；null 由响应明确表达为未知。
                org.slf4j.LoggerFactory.getLogger(getClass()).warn("商详博客点赞状态读取失败，shopId={}", shopId, error);
                rows.forEach(row -> row.setIsLike(null));
            }
        }
        return new ShopPage<>(rows, total, current, size);
    }
    /**
     * 读取时间窗口内的近期评价标签语料，不受首屏预览数量限制。
     *
     * @param shopId 店铺标识
     * @param since 近期统计窗口的起始时间
     * @param limit 最多读取的语料条数
     * @return 近期评价的作者与标签证据列表
     */
    public List<TagEvidence> reviewEvidence(Long shopId, LocalDateTime since, int limit) {
        return jdbc.query("""
                SELECT user_id,tags FROM tb_shop_review WHERE shop_id=? AND create_time>=?
                ORDER BY create_time DESC,id DESC LIMIT ?
                """, (r, n) -> {
            String value = r.getString("tags");
            var tags = value == null ? List.<ReviewTag>of() : Arrays.stream(value.replace("[", "")
                    .replace("]", "").replace("\"", "").split(",")).map(String::trim)
                    .filter(ReviewTag::contains).map(ReviewTag::valueOf).toList();
            return new TagEvidence(r.getLong("user_id"), tags, null);
        }, shopId, since, limit);
    }
    /**
     * 读取时间窗口内的近期探店博客语料，不受首屏预览数量限制。
     *
     * @param shopId 店铺标识
     * @param since 近期统计窗口的起始时间
     * @param limit 最多读取的语料条数
     * @return 近期探店笔记的作者与文本证据列表
     */
    public List<TagEvidence> blogEvidence(Long shopId, LocalDateTime since, int limit) {
        return jdbc.query("""
                SELECT user_id,title,content FROM tb_blog WHERE shop_id=? AND create_time>=?
                ORDER BY create_time DESC,id DESC LIMIT ?
                """, (r, n) -> new TagEvidence(r.getLong("user_id"), List.of(),
                Objects.requireNonNullElse(r.getString("title"), "") + "。" + Objects.requireNonNullElse(r.getString("content"), "")),
                shopId, since, limit);
    }
    /**
     * 以当前店铺为中心读取五公里内同类型店铺，排除自身并按距离、标识排序。
     *
     * @param center 作为周边推荐中心的店铺资料
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @return 带可用状态的周边分页结果
     */
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopPage<ShopRelatedShop> related(ShopBaseInfo center, long current, int size) {
        // 先按纬度裁剪，再用球面距离筛选，兼容跨日期变更线和高纬度。
        String candidates = """
                SELECT id,name,area,avg_price,score,
                12742017.6 * ASIN(SQRT(LEAST(1.0,POWER(SIN(RADIANS(y-?)/2),2)
                +COS(RADIANS(?))*COS(RADIANS(y))*POWER(SIN(RADIANS(x-?)/2),2)))) AS distance
                FROM tb_shop WHERE type_id=? AND id<>? AND x BETWEEN -180 AND 180
                AND y BETWEEN -90 AND 90 AND y BETWEEN ? AND ?
                """;
        Object[] args = {center.y(), center.y(), center.x(), center.typeId(), center.id(),
                center.y() - 0.045, center.y() + 0.045};
        String nearby = "SELECT * FROM (" + candidates + ") candidate WHERE distance<=5000";
        long total = jdbc.queryForObject("SELECT COUNT(*) FROM (" + nearby + ") matches", Long.class, args);
        var pageArgs = new ArrayList<>(Arrays.asList(args));
        pageArgs.add(size); pageArgs.add(Math.multiplyExact(current - 1, (long) size));
        var rows = jdbc.query(nearby + " ORDER BY distance ASC,id ASC LIMIT ? OFFSET ?", (r, n) ->
                new ShopRelatedShop(r.getLong("id"), r.getString("name"), r.getString("area"),
                        r.getObject("avg_price", Long.class), r.getObject("score", Integer.class),
                        r.getDouble("distance"), "附近同类店"), pageArgs.toArray());
        return new ShopPage<>(rows, total, current, size);
    }
    /**
     * 读取可空的数据库时间列并转换为本地日期时间。
     *
     * @param r 待转换的数据库或领域记录
     * @param field 待校验的字段名
     * @return 本地日期时间；数据库列为空时返回 null
     * @throws SQLException 读取数据库时间列失败
     */
    private static LocalDateTime time(ResultSet r, String field) throws SQLException {
        var timestamp = r.getTimestamp(field); return timestamp == null ? null : timestamp.toLocalDateTime();
    }
}

package com.dianping.shopdetail.repository;

import com.dianping.shopdetail.persistence.dataobject.ShopReview;
import com.dianping.shopdetail.persistence.mapper.ShopReviewMapper;
import org.springframework.stereotype.Repository;
import org.springframework.dao.DuplicateKeyException;
import java.util.*;
import com.dianping.shopdetail.model.ShopPage;
import com.dianping.shopdetail.model.ShopReviewSummary;
import org.springframework.transaction.annotation.*;

/**
 * 实现ShopReview仓储，负责数据库查询及持久化模型转换。
 */
@Repository
public class ShopReviewRepositoryImpl implements ShopReviewRepository {
    /**
     * 数据映射器。
     */
    private final ShopReviewMapper mapper;
    /**
     * 创建 ShopReviewRepositoryImpl，初始化所需依赖及实例状态。
     *
     * @param mapper 当前业务的 MyBatis 数据访问接口
     */
    public ShopReviewRepositoryImpl(ShopReviewMapper mapper) { this.mapper = mapper; }
    /**
     * 检查店铺记录是否存在。
     *
     * @param id 记录标识
     * @return 店铺是否存在
     */
    public boolean shopExists(Long id){ return mapper.shopExists(id); }
    /**
     * 锁定店铺行，串行化该店铺的业务写入。
     *
     * @param id 记录标识
     * @return 店铺是否存在且已成功取得行锁
     */
    public boolean lockShop(Long id){ return mapper.lockShop(id)!=null; }
    /**
     * 按作者和提交标识查询已持久化内容，用于幂等处理。
     *
     * @param userId 服务端确认的用户标识
     * @param requestId 客户端生成的 UUID 提交标识，用于幂等校验
     * @return 相同用户及提交标识对应的持久化记录；不存在时为空
     */
    public Optional<com.dianping.shopdetail.model.ShopReview> findSubmission(Long userId,String requestId){
        return Optional.ofNullable(mapper.findSubmission(userId,requestId)).map(this::toDomain);
    }
    /**
     * 插入经过领域校验的业务记录，并返回生成标识。
     *
     * @param review 评价业务数据
     * @return 新记录标识
     */
    public Long insert(com.dianping.shopdetail.model.ShopReview review){
        ShopReview row=toRow(review); try { mapper.insert(row); return row.getId(); }
        catch (DuplicateKeyException error) { throw new com.dianping.shopdetail.exception.DuplicateReviewSubmissionException(error); }
    }
    /**
     * 统计指定店铺的全部业务记录。
     *
     * @param id 记录标识
     * @return 匹配记录数或十倍总体评分总和
     */
    public long countByShopId(Long id){ return mapper.countByShopId(id); }
    /**
     * 汇总店铺全部评价的十倍总体评分。
     *
     * @param id 记录标识
     * @return 匹配记录数或十倍总体评分总和
     */
    public long sumOverallScoreByShopId(Long id){ return mapper.sumOverallScoreByShopId(id); }
    /**
     * 更新店铺评分与评价数；须与评价写入处于同一事务。
     *
     * @param id 记录标识
     * @param score 按实际分数的十倍保存的评分
     * @param total 全部匹配记录数
     */
    public void updateStatistics(Long id,int score,int total){ mapper.updateStatistics(id,score,total); }
    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param id 记录标识
     * @param offset 从 0 开始的记录偏移量
     * @param size 每页数量
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    public List<com.dianping.shopdetail.model.ShopReview> page(Long id,long offset,int size){return mapper.page(id,offset,size).stream().map(this::toDomain).toList();}
    /**
     * 在同一读取快照内取得分页明细和总数。
     *
     * @param id 记录标识
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    @Override
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopPage<com.dianping.shopdetail.model.ShopReview> pageWithTotal(Long id, long current, int size) {
        return new ShopPage<>(page(id, Math.multiplyExact(current - 1, (long) size), size), countByShopId(id), current, size);
    }
    /**
     * 在同一读取快照内汇总全店评价数量及均分。
     *
     * @param id 记录标识
     * @return 全店评价数量和五分制总体均分；无评价时均分为空
     */
    @Override
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopReviewSummary summarize(Long id) {
        return ShopReviewSummary.fromTotals(countByShopId(id), sumOverallScoreByShopId(id));
    }
    /**
     * 将数据库记录映射为领域业务数据。
     *
     * @param r 待转换的数据库或领域记录
     * @return 由持久化字段恢复的领域业务对象
     */
    private com.dianping.shopdetail.model.ShopReview toDomain(ShopReview r){return new com.dianping.shopdetail.model.ShopReview(r.getId(),r.getShopId(),r.getUserId(),r.getRequestId(),r.getOverallScore(),r.getTasteScore(),r.getEnvironmentScore(),r.getServiceScore(),r.getContent(),parseTags(r.getTags()),r.getCreateTime(),r.getUserName(),r.getUserIcon());}
    /**
     * 将领域业务数据映射为待写入数据库的记录。
     *
     * @param r 待转换的数据库或领域记录
     * @return 可交由 MyBatis 写入的持久化记录
     */
    private ShopReview toRow(com.dianping.shopdetail.model.ShopReview r){ShopReview x=new ShopReview();x.setShopId(r.shopId());x.setUserId(r.userId());x.setRequestId(r.requestId());x.setOverallScore(r.overallScore());x.setTasteScore(r.tasteScore());x.setEnvironmentScore(r.environmentScore());x.setServiceScore(r.serviceScore());x.setContent(r.content());x.setTags(toTags(r.tags()));x.setCreateTime(r.createTime());return x;}
    /**
     * 将已规范化的预设标签序列化为数据库 JSON 文本。
     *
     * @param tags 用户选择的预设标签
     * @return 可存入数据库的标签 JSON 文本
     */
    private static String toTags(List<String> tags){return "[\""+String.join("\",\"",tags)+"\"]";}
    /**
     * 将数据库保存的预设标签 JSON 文本还原为标签列表。
     *
     * @param value 待读取或转换的值
     * @return 从存储文本还原的预设标签列表
     */
    private static List<String> parseTags(String value){if(value==null||value.length()<4)return List.of();return Arrays.stream(value.substring(2,value.length()-2).split("\",\"" )).filter(s->!s.isBlank()).toList();}

}

package com.dianping.shopdetail.repository;

import com.dianping.shopdetail.model.ShopSetmeal;
import com.dianping.shopdetail.model.ShopSetmealItem;
import com.dianping.shopdetail.model.ShopPage;
import org.springframework.transaction.annotation.*;
import com.dianping.shopdetail.persistence.mapper.ShopSetmealMapper;
import org.springframework.stereotype.Repository;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 批量读取套餐与菜品，将持久化数据转换为完整领域模型。
 */
@Repository
public class ShopSetmealRepositoryImpl implements ShopSetmealRepository {
    /**
     * 数据映射器。
     */
    private final ShopSetmealMapper mapper;

    /**
     * 创建 ShopSetmealRepositoryImpl，初始化所需依赖及实例状态。
     *
     * @param mapper 当前业务的 MyBatis 数据访问接口
     */
    public ShopSetmealRepositoryImpl(ShopSetmealMapper mapper) {
        this.mapper = mapper;
    }

    /**
     * 检查店铺记录是否存在。
     *
     * @param shopId 店铺标识
     * @return 店铺是否存在
     */
    @Override
    public boolean shopExists(Long shopId) {
        return mapper.shopExists(shopId);
    }

    /**
     * 查询当前店铺的上架套餐并批量补齐固定菜品明细。
     *
     * @param shopId 店铺标识
     * @return 有序上架套餐列表，每项包含固定菜品明细
     */
    @Override
    public List<ShopSetmeal> findPublishedByShopId(Long shopId) {
        return map(mapper.findPublished(shopId));
    }

    /**
     * 统计当前店铺上架套餐总数。
     *
     * @param shopId 店铺标识
     * @return 匹配记录数或十倍总体评分总和
     */
    public long countPublished(Long shopId) { return mapper.countPublished(shopId); }

    /**
     * 按展示顺序分页读取上架套餐。
     *
     * @param shopId 店铺标识
     * @param offset 从 0 开始的记录偏移量
     * @param size 每页数量
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    public List<ShopSetmeal> pagePublished(Long shopId, long offset, int size) {
        return map(mapper.pagePublished(shopId, offset, size));
    }

    /**
     * 批量补齐套餐菜品明细并映射为领域模型。
     *
     * @param rows 有序数据库记录集合
     * @return 转换或执行后的业务响应，保留对应分项状态
     */
    private List<ShopSetmeal> map(List<com.dianping.shopdetail.persistence.dataobject.ShopSetmeal> rows) {
        if (rows.isEmpty()) return List.of();
        var items = mapper.findItems(rows.stream().map(row -> row.getId()).toList()).stream()
                .collect(Collectors.groupingBy(row -> row.getSetmealId()));
        return rows.stream().map(row -> new ShopSetmeal(row.getId(), row.getShopId(), row.getName(),
                row.getCoverImage(), row.getPrice(), row.getOriginalPrice(), row.getPeople(),
                row.getDescription(), row.getRules(),
                items.getOrDefault(row.getId(), List.of()).stream()
                        .map(item -> new ShopSetmealItem(item.getName(), item.getQuantity(), item.getUnit()))
                        .toList())).toList();
    }

    /**
     * 在同一读取快照内取得分页明细和总数。
     *
     * @param shopId 店铺标识
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    @Override
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopPage<ShopSetmeal> pageWithTotal(Long shopId, long current, int size) {
        return new ShopPage<>(pagePublished(shopId, Math.multiplyExact(current - 1, (long) size), size),
                countPublished(shopId), current, size);
    }
}

package com.dianping.shopdetail.repository;
import com.dianping.shopdetail.model.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.*;
import java.time.LocalDateTime;

/**
 * 普通券与秒杀券共用稳定排序，库存与时间只用于展示状态。
 */
@Repository
public class ShopVoucherRepositoryImpl implements ShopVoucherRepository {
    /**
     * 关系数据库查询模板。
     */
    private final JdbcTemplate jdbc;
    /**
     * 创建 ShopVoucherRepositoryImpl，初始化所需依赖及实例状态。
     *
     * @param jdbc 关系数据库查询模板
     */
    public ShopVoucherRepositoryImpl(JdbcTemplate jdbc) { this.jdbc = jdbc; }
    /**
     * 分页读取当前店铺的业务记录，返回有序明细及总数。
     *
     * @param shopId 店铺标识
     * @param current 从 1 开始的页码
     * @param size 每页数量
     * @param now 本次读取或创建使用的时间基准
     * @return 当前页结果；无匹配数据时为空记录集合
     */
    @Transactional(readOnly = true, propagation = Propagation.REQUIRES_NEW, isolation = Isolation.REPEATABLE_READ)
    public ShopPage<ShopVoucher> page(Long shopId, long current, int size, LocalDateTime now) {
        String from = """
                FROM tb_voucher v LEFT JOIN tb_seckill_voucher s ON s.voucher_id=v.id
                WHERE v.shop_id=? AND v.status=1
                AND (v.type=0 OR (v.type=1 AND s.begin_time IS NOT NULL AND s.end_time>?))
                """;
        long total = jdbc.queryForObject("SELECT COUNT(*) " + from, Long.class, shopId, now);
        var rows = jdbc.query("""
                SELECT v.*,s.stock,s.begin_time,s.end_time,
                CASE WHEN v.type=0 OR (s.begin_time<=? AND s.stock>0) THEN 0 ELSE 1 END AS unavailable
                """ + from + " ORDER BY unavailable ASC,v.pay_value ASC,v.id ASC LIMIT ? OFFSET ?",
                (r, n) -> {
                    var begin = r.getTimestamp("begin_time");
                    var end = r.getTimestamp("end_time");
                    Integer stock = r.getObject("stock", Integer.class);
                    String state = r.getInt("type") == 0 ? "AVAILABLE"
                            : begin.toLocalDateTime().isAfter(now) ? "UPCOMING"
                            : stock == null || stock <= 0 ? "SOLD_OUT" : "AVAILABLE";
                    return new ShopVoucher(r.getLong("id"), r.getLong("shop_id"), r.getString("title"),
                            r.getString("sub_title"), r.getString("rules"), r.getLong("pay_value"),
                            r.getLong("actual_value"), r.getInt("type"), stock,
                            begin == null ? null : begin.toLocalDateTime(), end == null ? null : end.toLocalDateTime(), state);
                }, now, shopId, now, size, Math.multiplyExact(current - 1, (long) size));
        return new ShopPage<>(rows, total, current, size);
    }
}

