package com.dianping.feed;

import com.dianping.entity.Blog;
import com.dianping.constant.RedisConstants;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ZSetOperations;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.Collection;
import java.util.List;
import java.util.Set;
import java.util.UUID;

@Component
public class FeedCache {
    private final StringRedisTemplate redis;
    private final FeedProperties properties;
    //token用于标识这是哪一次重建，防止旧请求覆盖新状态
    //signature用于标识“缓存是按什么条件构建的”，比如30:[10,20]表示展示30天，作者列表为10，20
    //这段Lua脚本用于完成缓存重建
    /**
     * 3个key分别是：
     * feed:state:{userId}表示缓存重建状态 存的是token
     * feed:state:{userId}:empty 空结果标记  存的是0或1
     * feed:{userId} 存的是时间线zset
     * 3个参数分别是：本次重建的token、重建完成后的签名、ttl
     * 三个功能：
     * 1.先校验token，判断本轮构建是否仍然有效，无效就提前返回
     * 2.更新empty标记
     * 3.更新state，从token换为signature
     */
    private static final DefaultRedisScript<Long> COMPLETE = new DefaultRedisScript<>("""
            if redis.call('GET', KEYS[1]) ~= ARGV[1] then return 0 end
            local empty = '1' 
            if redis.call('ZCARD', KEYS[3]) > 0 then empty = '0' end
            redis.call('SET', KEYS[2], empty, 'EX', ARGV[3])
            redis.call('SET', KEYS[1], ARGV[2], 'EX', ARGV[3])
            redis.call('EXPIRE', KEYS[3], ARGV[3])
            return 1
            """, Long.class);

    public FeedCache(StringRedisTemplate redis, FeedProperties properties) {
        this.redis = redis; this.properties = properties;
    }
    //辅助方法
    private String key(long userId) { return RedisConstants.FEED_KEY + userId; }
    //stateKey在重建期间存token，重建完成后存签名
    private String stateKey(long userId) { return RedisConstants.FEED_STATE_KEY + userId; }

    /**
     * 判断当前用户的缓存是否可以使用
     * @param userId 用户id
     * @param signature 签名
     * @return 布尔值
     */
    public boolean ready(long userId, String signature) {
        //判断缓存是否重建完成（如果存的还是token就说明没完成），并且是否符合当前条件（作者列表或者保留天数变了就需要重建新的缓存）
        if (!signature.equals(redis.opsForValue().get(stateKey(userId)))) return false;
        //判空
        String empty = redis.opsForValue().get(stateKey(userId) + ":empty");
        //1就是确实为空，0的话就要保证zset的key必须存在，注意空结果也是可用缓存
        return "1".equals(empty) || ("0".equals(empty) && redis.hasKey(key(userId)));
    }


    //生成本轮构建的唯一标识token，写入redis状态key
    public String beginBuild(long userId) {
        String token = "building:" + UUID.randomUUID();
        redis.opsForValue().set(stateKey(userId), token, Duration.ofDays(properties.retentionDays() + 1L));
        return token;
    }

    //让其他类在写完缓存之后调用Lua脚本，完成本轮构建的收尾工作
    public void complete(long userId, String signature, String token) {
        redis.execute(COMPLETE, List.of(stateKey(userId), stateKey(userId) + ":empty", key(userId)),
                token, signature, String.valueOf(Duration.ofDays(properties.retentionDays() + 1L).toSeconds()));
    }

    //清除构建状态
    public void invalidate(long userId) { redis.delete(stateKey(userId)); }

    //向zset中添加元素
    public void add(long userId, List<Blog> blogs, long lower) {
        for (Blog blog : blogs) {
            long score = FeedTimeline.score(blog);
            if (score >= lower) {
                redis.opsForZSet().add(key(userId), blog.getId().toString(), score);
                redis.opsForValue().set(stateKey(userId) + ":empty", "0", Duration.ofDays(properties.retentionDays() + 1L));
            }
        }
        prune(userId, lower);
        redis.expire(key(userId), Duration.ofDays(properties.retentionDays() + 1L));
    }

    //清理过期博客，负无穷到lower-1
    public void prune(long userId, long lower) {
        redis.opsForZSet().removeRangeByScore(key(userId), Double.NEGATIVE_INFINITY, lower - 1);
    }

    //按时间倒序读取候选博客ID
    public List<Long> candidates(long userId, long lower, long upper, long offset, int limit) {
        Set<ZSetOperations.TypedTuple<String>> rows = redis.opsForZSet()
                .reverseRangeByScoreWithScores(key(userId), lower, upper, offset, limit);
        if (rows == null) throw new IllegalStateException("Feed 缓存读取失败");
        return rows.stream().map(row -> Long.parseLong(row.getValue())).toList();
    }

    //删除指定博客
    public void remove(long userId, Collection<Long> blogIds) {
        if (!blogIds.isEmpty()) redis.opsForZSet().remove(key(userId), blogIds.stream().map(String::valueOf).toArray());
    }
}

package com.dianping.feed;

import lombok.Data;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

@Data
@Component
@ConfigurationProperties(prefix = "feed")
public class FeedProperties {
    private int retentionDays = 30; //最多保存时间
    private int hotAuthorThreshold = 1000; //热点作者阈值
    private int pageSize = 10; //每页多少篇
    private int batchSize = 200; //一批处理多少
    private long leaseSeconds = 300; //后台消费者认领任务之后占用该任务的有效时间

    public int retentionDays() { return Math.max(1, retentionDays); }
    public int threshold() { return Math.max(1, hotAuthorThreshold); }
    public int pageSize() { return Math.max(1, Math.min(100, pageSize)); }
    public int batchSize() { return Math.max(1, Math.min(1000, batchSize)); }
}

package com.dianping.feed;

import com.dianping.entity.Blog;
import com.dianping.entity.Follow;
import com.dianping.mapper.BlogMapper;
import com.dianping.mapper.FollowMapper;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import org.springframework.stereotype.Repository;

import java.time.LocalDateTime;
import java.util.Collection;
import java.util.List;

/** Feed 的业务数据查询入口；通用查询使用 MyBatis-Plus，定制查询定义于 Mapper XML。 */
@Repository
public class FeedRepository {
    private final BlogMapper blogMapper;
    private final FollowMapper followMapper;

    public FeedRepository(BlogMapper blogs, FollowMapper follows) {
        this.blogMapper = blogs;
        this.followMapper = follows;
    }
    //一个记录内部类，完整名称就是FeedRepository.Author,嵌套的record类隐式是static类型
    //相当于一个摘要，不需要查询完整的数据
    public record Author(long id, boolean hot) {}

    /**
     * 查询关注的作者
     * @param userId 用户id
     * @param threshold 热点作者阈值
     * @return 作者列表
     */
    public List<Author> authors(long userId, int threshold) {
        return followMapper.selectFeedAuthors(userId, threshold);
    }

    /**
     * 根据作者id和阈值判断是否是热点作者
     * @param authorId 作者id
     * @param threshold 热点作者阈值
     * @return
     */
    public boolean hot(long authorId, int threshold) {
        // 关系表是持久化来源，避免历史用户统计未初始化造成漏推或错误分类。
        Long fans = followMapper.selectCount(Wrappers.<Follow>lambdaQuery().eq(Follow::getFollowUserId, authorId));
        return fans != null && fans >= threshold;
    }
    //判断是否有关注关系
    public boolean follows(long userId, long authorId) {
        Long count = followMapper.selectCount(Wrappers.<Follow>lambdaQuery()
                .eq(Follow::getUserId, userId).eq(Follow::getFollowUserId, authorId));
        return count != null && count > 0;
    }

    /**
     * 用于分批查询某个作者的粉丝ID
     * @param authorId 作者Id
     * @param afterUserId 游标，只查询id大于它的用户
     * @param limit 本次最多查询多少个粉丝
     * @return
     */
    public List<Long> fans(long authorId, long afterUserId, int limit) {
        return followMapper.selectFeedFans(authorId, afterUserId, limit);
    }

    //根据id查询博客
    public Blog blog(long id) {
        return blogMapper.selectById(id);
    }

    //根据id批量查询博客
    public List<Blog> blogByIds(Collection<Long> ids) {
        if (ids.isEmpty()) return List.of();
        return blogMapper.selectByIds(ids);
    }

    //查询一段时间内的博客
    public List<Blog> recent(Collection<Long> authors, LocalDateTime lower, LocalDateTime upper, int limit) {
        if (authors.isEmpty()) return List.of();
        return blogMapper.selectFeedRecent(authors, lower, upper, limit);
    }

    //查询历史博客，通常就是新关注了一个用户，获得一定范围的历史博客
    public List<Blog> history(Collection<Long> authors, LocalDateTime lower, long afterBlogId, int limit) {
        if (authors.isEmpty()) return List.of();
        return blogMapper.selectFeedHistory(authors, lower, afterBlogId, limit);
    }

}

package com.dianping.feed;

import com.dianping.dto.ScrollResult;
import com.dianping.dto.UserDTO;
import com.dianping.entity.Blog;
import com.dianping.entity.User;
import com.dianping.result.Result;
import com.dianping.service.UserService;
import com.dianping.utils.UserHolder;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

@Slf4j
@Service
public class FeedService {
    private final FeedRepository repository;
    private final FeedCache cache;
    private final FeedProperties properties;
    private final UserService userService;

    public FeedService(FeedRepository repository, FeedCache cache, FeedProperties properties, UserService users) {
        this.repository = repository;
        this.cache = cache;
        this.properties = properties;
        this.userService = users;
    }

    //计算feed的时间下界
    public long lower() {
        return Instant.now()
                .minus(Duration.ofDays(properties.retentionDays()))
                .toEpochMilli();
    }


    /**
     *
     * @param lastId 时间游标，表示本次查询的时间上界
     * @param offset 在lastId这个时点已经查询过的博客数量
     * @return
     */
    public Result<ScrollResult> read(long lastId, int offset) {
        UserDTO user = UserHolder.getUser();
        if (user == null || user.getId() == null) return Result.error("请先登录");
        //非负+防止整数溢出
        if (lastId < 0 || offset < 0 || offset > Integer.MAX_VALUE - properties.pageSize()) {
            return Result.error("分页参数无效");
        }
        try {
            long upper = Math.min(lastId, System.currentTimeMillis());
            long lower = lower();
            List<FeedRepository.Author> authors = repository.authors(user.getId(), properties.threshold());
            //分为两组，一组普通作者一组热点作者
            List<Long> ordinary = authors.stream().filter(a -> !a.hot()).map(FeedRepository.Author::id).toList();
            List<Long> hot = authors.stream().filter(FeedRepository.Author::hot).map(FeedRepository.Author::id).toList();
            //候选数量，需要先跳过offset条博客
            int count = offset + properties.pageSize();
            List<Blog> candidates;
            //查询普通作者
            try {
                ensureCache(user.getId(), ordinary, lower);
                candidates = cachedCandidates(user.getId(), ordinary, lower, upper, count);
            } catch (RuntimeException cacheFailure) {
                log.warn("Feed 缓存不可用，改用数据库，userId={}", user.getId());
                //缓存不可用时降级数据库
                candidates = new ArrayList<>(repository.recent(ordinary, FeedTimeline.time(lower), FeedTimeline.time(upper), count));
            }
            //查询热点作者
            candidates.addAll(repository.recent(hot, FeedTimeline.time(lower), FeedTimeline.time(upper), count));
            ScrollResult result = FeedTimeline.page(candidates, upper, offset, properties.pageSize(), lower);
            //补充作者信息
            enrich(result);
            return Result.success(result);
        } catch (RuntimeException failure) {
            log.error("关注动态读取失败，userId={}", user.getId(), failure);
            return Result.error("关注动态加载失败，请稍后重试。");
        }
    }

    /**
     * 确保缓存存在，不存在就重建
     * @param userId
     * @param ordinary 当前用户关注的普通作者id列表
     * @param lower
     */
    private void ensureCache(long userId, List<Long> ordinary, long lower) {
        String signature = properties.retentionDays() + ":" + ordinary;
        //没准备好就重建缓存
        if (!cache.ready(userId, signature)) {
            String token = cache.beginBuild(userId);
            long after = 0;
            while (true) {
                List<Blog> blogs = repository.history(ordinary, FeedTimeline.time(lower), after, properties.batchSize());
                cache.add(userId, blogs, lower);
                if (blogs.size() < properties.batchSize()) break;
                after = blogs.getLast().getId();
            }
            cache.complete(userId, signature, token);
        }//清理窗口外的数据
        cache.prune(userId, lower);
    }

    /**
     * 读取缓存里的普通作者的博客
     * @param userId 用户id
     * @param ordinary 用户关注的普通作者id
     * @param lower 时间下界
     * @param upper 时间上界
     * @param count 本次最多准备多少篇
     * @return 博客列表
     */
    private List<Blog> cachedCandidates(long userId, List<Long> ordinary, long lower, long upper, int count) {
        Set<Long> allowed = new HashSet<>(ordinary);
        List<Blog> result = new ArrayList<>();
        long scanned = 0;//记录扫描位置
        while (result.size() < count) {
            List<Long> ids = cache.candidates(userId, lower, upper, scanned, properties.batchSize());
            if (ids.isEmpty()) break;
            Map<Long, Blog> blogs = new HashMap<>();
            repository.blogByIds(ids).forEach(blog -> blogs.put(blog.getId(), blog));
            for (Long id : ids) {
                Blog blog = blogs.get(id);
                if (blog != null && allowed.contains(blog.getUserId()) && FeedTimeline.score(blog) >= lower
                        && FeedTimeline.score(blog) <= upper) result.add(blog);
            }
            scanned += ids.size();
            if (ids.size() < properties.batchSize()) break;
        }
        return result;
    }

    //补充作者基本信息
    private void enrich(ScrollResult result) {
        List<?> blogs = result.getList();
        List<Long> authorIds = blogs.stream().map(b -> ((Blog) b).getUserId()).distinct().toList();
        if (authorIds.isEmpty()) return;
        Map<Long, User> authors = new HashMap<>();
        userService.listByIds(authorIds).forEach(user -> authors.put(user.getId(), user));
        for (Object value : blogs) {
            Blog blog = (Blog) value;
            User author = authors.get(blog.getUserId());
            if (author != null) {
                blog.setName(author.getNickName());
                blog.setIcon(author.getIcon());
            }
        }
    }

}

package com.dianping.feed;

import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import com.dianping.entity.FeedTask;
import com.dianping.entity.Follow;
import com.dianping.mapper.FeedTaskMapper;
import com.dianping.mapper.FollowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.List;

@Repository
public class FeedTaskRepository {
    private final FeedTaskMapper feedTaskMapper;
    private final FollowMapper followMapper;
    private final FeedProperties properties;
    public FeedTaskRepository(FeedTaskMapper tasks, FollowMapper follows, FeedProperties properties) {
        this.feedTaskMapper = tasks;
        this.followMapper = follows;
        this.properties = properties;
    }

    //在博客发布成功后调用
    public void publish(long blogId, long authorId) {
        enqueue("PUBLISH", blogId, authorId, null);
    }

    /**
     * 处理关注和取关
     * @param userId 用户id
     * @param authorId 作者id
     * @param followed true表示关注，false表示取关
     * 关注时发回填backfill任务，取关时发cleanup任务
     * 关注后刚好到阈值或者取关后刚到低于阈值发reclassify任务
     */
    public void relationship(long userId, long authorId, boolean followed) {
        enqueue(followed ? "BACKFILL" : "CLEANUP", null, authorId, userId);
        Long fans = followMapper.selectCount(Wrappers.<Follow>lambdaQuery().eq(Follow::getFollowUserId, authorId));
        if (fans != null && fans == (followed ? properties.threshold() : properties.threshold() - 1L)) {
            // 只在阈值边界分发失效通知，避免热点作者每新增一个粉丝都遍历所有粉丝。
            // 分类变化不依赖通知及时完成，读取时分类签名也会触发补齐。
            enqueue("RECLASSIFY", null, authorId, null);
        }
    }

    //创建并持久化feed任务
    private void enqueue(String kind, Long blogId, long authorId, Long userId) {
        FeedTask task = new FeedTask()
                .setKind(kind)
                .setBlogId(blogId)
                .setAuthorId(authorId)
                .setUserId(userId)
                .setStatus("PENDING")
                .setCursorId(0L)
                .setAttempts(0)
                .setNextAttempt(now());
        if (feedTaskMapper.insert(task) != 1) {
            throw new IllegalStateException("Feed 任务入队失败");
        }
    }
    //查询到期任务
    public List<FeedTask> due(int limit) {
        return feedTaskMapper.selectDue(Timestamp.from(Instant.now()), limit);
    }
    //认领任务
    public boolean claim(FeedTask task, String owner, long leaseSeconds) {
        Instant now = Instant.now();
        return feedTaskMapper.claim(task, owner, Timestamp.from(now),
                Timestamp.from(now.plusSeconds(Math.max(30, leaseSeconds)))) == 1;
    }
    //保存任务的处理进度
    public void progress(FeedTask task, String owner, long cursor) {
        requireOwner(feedTaskMapper.progress(task.getId(), owner, cursor, Timestamp.from(Instant.now())));
    }
    //结束任务
    public void finish(FeedTask task, String owner, String status, String reason) {
        requireOwner(feedTaskMapper.finish(task.getId(), owner, status, reason, Timestamp.from(Instant.now())));
    }
    //重试任务
    public void retry(FeedTask task, String owner, RuntimeException failure) {
        long delay = Math.min(300, 1L << Math.min(9, task.getAttempts() + 1));
        feedTaskMapper.retry(task.getId(), owner, failure.getClass().getSimpleName(), Timestamp.from(Instant.now().plusSeconds(delay)));
    }
    //获取UTC时间
    private LocalDateTime now() {
        return LocalDateTime.now(ZoneOffset.UTC);
    }
    //通过执行sql之后影响的行数确认当前worker仍然持有租约
    private void requireOwner(int changed) {
        if (changed != 1) throw new IllegalStateException("Feed 任务租约已被其他消费者接管");
    }
}

package com.dianping.feed;

import com.dianping.dto.ScrollResult;
import com.dianping.entity.Blog;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.*;


public final class FeedTimeline {
    private FeedTimeline() {}

    //把博客发布时间转换为毫秒时间戳
    public static long score(Blog blog) {
        return blog.getCreateTime().toInstant(ZoneOffset.UTC).toEpochMilli();
    }
    //反向转换
    public static LocalDateTime time(long millis) {
        return LocalDateTime.ofInstant(Instant.ofEpochMilli(millis), ZoneOffset.UTC);
    }

    /**
     *
     * @param candidates 待处理的候选博客
     * @param upper 本次查询的时间上界
     * @param offset 在upper这个时点已经查询过多少篇
     * @param size 每页最多多少篇
     * @param lower 本次查询的时间下界
     * @return 统一的scrollResult
     * upper+offset就是总的游标，表示已经查询过的部分
     */
    public static ScrollResult page(List<Blog> candidates, long upper, int offset, int size, long lower) {
        //过滤并去重
        Map<Long, Blog> unique = new LinkedHashMap<>();
        for (Blog blog : candidates) {
            if (blog.getCreateTime() != null && score(blog) >= lower && score(blog) <= upper) unique.put(blog.getId(), blog);
        }
        //统一排序
        List<Blog> sorted = unique.values().stream()
                .sorted(Comparator //先按发布时间倒序，新的在前
                        .comparingLong(FeedTimeline::score).reversed()
                        //发布时间相同的再按博客ID的字符串顺序倒序，和redis zset保持一致
                        .thenComparing(blog -> blog.getId().toString(), Comparator.reverseOrder()))
                .toList();

        int skip = offset;
        List<Blog> page = new ArrayList<>() ;
        for (Blog blog : sorted) {
            if (score(blog) == upper && skip > 0) { skip--; continue; }
            page.add(blog);
            if (page.size() == size) break;
        }

        ScrollResult result = new ScrollResult();
        //计算本页最后一篇博客的时间，就是下一次查询的upper
        long minTime = page.isEmpty() ? upper : score(page.getLast());
        //计算minTime这个时点上有多少篇博客，就是下一次查询的offset
        int sameTime = (int) page.stream().filter(blog -> score(blog) == minTime).count();

        result.setList(page);
        result.setMinTime(minTime);
        result.setOffset(page.isEmpty() ? offset : sameTime + (minTime == upper ? offset : 0));
        return result;
    }
}

