import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.UUID;
import java.util.concurrent.TimeUnit;

@Slf4j
@Service
public class AvatarServiceImpl implements AvatarService {
    private static final long MAX_IMAGE_BYTES = 5L * 1024 * 1024;
    private static final String PUBLIC_PREFIX = "/imgs/";
    private static final String TEMP_PREFIX = "avatars/tmp/";
    private static final String PERMANENT_PREFIX = "avatars/";
    private static final List<AvatarOptionVO> DEFAULT_AVATARS = List.of(
            new AvatarOptionVO("default-01", "/imgs/icons/default-01.png"),
            new AvatarOptionVO("default-02", "/imgs/icons/default-02.png"),
            new AvatarOptionVO("default-03", "/imgs/icons/default-03.png"),
            new AvatarOptionVO("default-04", "/imgs/icons/default-04.png"),
            new AvatarOptionVO("default-05", "/imgs/icons/default-05.png"),
            new AvatarOptionVO("default-06", "/imgs/icons/default-06.png"),
            new AvatarOptionVO("default-07", "/imgs/icons/default-07.png"),
            new AvatarOptionVO("default-08", "/imgs/icons/default-08.png")
    );

    private final UserService userService;
    private final StringRedisTemplate stringRedisTemplate;
    private final Path baseDirectory;

    @Autowired
    public AvatarServiceImpl(UserService userService,
                             StringRedisTemplate stringRedisTemplate,
                             com.dianping.config.UploadProperties uploadProperties) {
        this(userService, stringRedisTemplate, uploadProperties.getDirectory());
    }

    public AvatarServiceImpl(UserService userService,
                             StringRedisTemplate stringRedisTemplate,
                             Path baseDirectory) {
        if (baseDirectory == null) throw new IllegalArgumentException("上传目录未配置");
        this.userService = userService;
        this.stringRedisTemplate = stringRedisTemplate;
        this.baseDirectory = baseDirectory.toAbsolutePath().normalize();
    }

    @Override
    public Result<String> uploadAvatar(MultipartFile image) {
        UserDTO currentUser = UserHolder.getUser();
        if (currentUser == null || currentUser.getId() == null) return Result.error("请先登录");
        if (image == null || image.isEmpty()) return Result.error("请选择图片文件");
        if (image.getSize() > MAX_IMAGE_BYTES) return Result.error("头像图片不能超过 5 MB");

        String suffix = suffixOf(image.getOriginalFilename());
        if (!isSupportedSuffix(suffix)) return Result.error("仅支持 JPG、PNG 格式");
        if (image.getContentType() == null || !image.getContentType().startsWith("image/")) {
            return Result.error("文件内容类型必须为图片");
        }

        try {
            byte[] bytes = image.getBytes();
            BufferedImage source = ImageIO.read(new ByteArrayInputStream(bytes));
            if (source == null) return Result.error("图片内容无效");
            byte[] normalized = centerCrop(source, suffix);
            String relative = TEMP_PREFIX + currentUser.getId() + "/" + UUID.randomUUID() + "." + suffix;
            Path target = safeResolve(relative);
            Files.createDirectories(target.getParent());
            Files.write(target, normalized, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
            try {
                stringRedisTemplate.opsForValue().set(ownerKey(relative), currentUser.getId().toString(),
                        RedisConstants.AVATAR_UPLOAD_OWNER_TTL_MINUTES, TimeUnit.MINUTES);
            } catch (RuntimeException redisFailure) {
                Files.deleteIfExists(target);
                return Result.error("上传服务不可用，请稍后重试");
            }
            return Result.success(PUBLIC_PREFIX + relative);
        } catch (IOException | IllegalArgumentException exception) {
            log.debug("头像上传失败", exception);
            return Result.error("头像上传失败");
        }
    }

    @Override
    public List<AvatarOptionVO> defaultAvatars() {
        return new ArrayList<>(DEFAULT_AVATARS);
    }

    @Override
    public Result<AvatarVO> updateAvatar(AvatarUpdateDTO request) {
        UserDTO currentUser = UserHolder.getUser();
        if (currentUser == null || currentUser.getId() == null) return Result.error("请先登录");
        if (request == null || request.getSourceType() == null) return Result.error("头像来源不能为空");

        String sourceType = request.getSourceType().trim().toUpperCase(Locale.ROOT);
        boolean hasUpload = hasText(request.getUploadPath());
        boolean hasDefault = hasText(request.getDefaultId());
        if (hasUpload == hasDefault) return Result.error("只能选择一种头像来源");

        String nextIcon;
        if ("DEFAULT".equals(sourceType) && hasDefault && !hasUpload) {
            nextIcon = defaultIcon(request.getDefaultId());
            if (nextIcon == null) return Result.error("默认头像不存在");
        } else if ("UPLOAD".equals(sourceType) && hasUpload && !hasDefault) {
            nextIcon = promoteTemporaryFile(request.getUploadPath(), currentUser.getId());
            if (nextIcon == null) return Result.error("头像文件已失效，请重新上传");
        } else {
            return Result.error("头像来源参数错误");
        }

        User user = userService.getById(currentUser.getId());
        if (user == null) return Result.error("用户不存在");
        String oldIcon = user.getIcon();
        user.setIcon(nextIcon);
        if (!userService.updateById(user)) {
            if ("UPLOAD".equals(sourceType)) deleteRelative(nextIcon);
            return Result.error("头像保存失败");
        }
        deleteUserUploadIfNecessary(oldIcon, nextIcon);
        return Result.success(new AvatarVO(nextIcon, sourceType));
    }

    @Override
    @Scheduled(fixedDelayString = "${app.upload.avatar-cleanup-interval-ms:600000}", initialDelayString = "${app.upload.avatar-cleanup-initial-delay-ms:600000}")
    public void cleanupExpiredTemporaryFiles() {
        Path temporaryRoot = safeResolve(TEMP_PREFIX);
        if (!Files.isDirectory(temporaryRoot)) return;
        try (var files = Files.walk(temporaryRoot)) {
            files.filter(Files::isRegularFile).forEach(file -> {
                String relative = baseDirectory.relativize(file).toString().replace('\\', '/');
                try {
                    if (stringRedisTemplate.opsForValue().get(ownerKey(relative)) == null) {
                        Files.deleteIfExists(file);
                    }
                } catch (RuntimeException | IOException exception) {
                    log.warn("清理头像临时文件失败: {}", relative, exception);
                }
            });
        } catch (IOException exception) {
            log.warn("扫描头像临时目录失败", exception);
        }
    }

    private String promoteTemporaryFile(String publicPath, Long userId) {
        String relative = relativePath(publicPath);
        if (relative == null || !relative.startsWith(TEMP_PREFIX + userId + "/")) return null;
        String owner;
        try {
            owner = stringRedisTemplate.opsForValue().get(ownerKey(relative));
        } catch (RuntimeException exception) {
            return null;
        }
        if (!userId.toString().equals(owner)) return null;

        Path source = safeResolve(relative);
        if (!Files.isRegularFile(source)) return null;
        String filename = Path.of(relative).getFileName().toString();
        String permanent = PERMANENT_PREFIX + userId + "/" + filename;
        Path target = safeResolve(permanent);
        try {
            Files.createDirectories(target.getParent());
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
            try {
                stringRedisTemplate.delete(ownerKey(relative));
            } catch (RuntimeException cleanupFailure) {
                // 文件已经绑定到正式路径；所有权键会自然过期，不能把已完成的保存报告为失败。
                log.warn("清理头像临时文件所有权记录失败: {}", relative, cleanupFailure);
            }
            return PUBLIC_PREFIX + permanent;
        } catch (IOException | RuntimeException exception) {
            log.debug("头像临时文件绑定失败", exception);
            return null;
        }
    }

    private String defaultIcon(String id) {
        return DEFAULT_AVATARS.stream()
                .filter(option -> option.getId().equals(id))
                .map(AvatarOptionVO::getIcon)
                .findFirst()
                .orElse(null);
    }

    private void deleteUserUploadIfNecessary(String oldIcon, String nextIcon) {
        if (oldIcon == null || oldIcon.equals(nextIcon)) return;
        if (oldIcon.startsWith(PUBLIC_PREFIX + PERMANENT_PREFIX)) deleteRelative(oldIcon);
    }

    private void deleteRelative(String publicPath) {
        String relative = relativePath(publicPath);
        if (relative == null || !relative.startsWith(PERMANENT_PREFIX)) return;
        try {
            Files.deleteIfExists(safeResolve(relative));
        } catch (IOException | IllegalArgumentException exception) {
            log.warn("删除旧头像失败: {}", publicPath, exception);
        }
    }

    private byte[] centerCrop(BufferedImage source, String suffix) throws IOException {
        int size = Math.min(source.getWidth(), source.getHeight());
        int x = (source.getWidth() - size) / 2;
        int y = (source.getHeight() - size) / 2;
        int imageType = "png".equals(suffix) ? BufferedImage.TYPE_INT_ARGB : BufferedImage.TYPE_INT_RGB;
        BufferedImage square = new BufferedImage(size, size, imageType);
        Graphics2D graphics = square.createGraphics();
        try {
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            graphics.drawImage(source, 0, 0, size, size, x, y, x + size, y + size, null);
        } finally {
            graphics.dispose();
        }
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        ImageIO.write(square, suffix, output);
        return output.toByteArray();
    }

    private Path safeResolve(String relative) {
        String clean = relative.replace('\\', '/');
        while (clean.startsWith("/")) clean = clean.substring(1);
        Path resolved = baseDirectory.resolve(clean).normalize();
        if (!resolved.startsWith(baseDirectory)) throw new IllegalArgumentException("路径越界");
        return resolved;
    }

    private String relativePath(String publicPath) {
        if (publicPath == null || !publicPath.startsWith(PUBLIC_PREFIX)) return null;
        String relative = publicPath.substring(PUBLIC_PREFIX.length());
        if (relative.contains("..") || relative.contains("\\")) return null;
        return relative;
    }

    private String ownerKey(String relative) {
        return RedisConstants.AVATAR_UPLOAD_OWNER_KEY + relative;
    }

    private String suffixOf(String filename) {
        if (filename == null) return null;
        int dot = filename.lastIndexOf('.');
        if (dot < 0 || dot == filename.length() - 1) return null;
        String suffix = filename.substring(dot + 1).toLowerCase(Locale.ROOT);
        return "jpeg".equals(suffix) ? "jpg" : suffix;
    }

    private boolean isSupportedSuffix(String suffix) {
        return "jpg".equals(suffix) || "png".equals(suffix);
    }

    private boolean hasText(String value) {
        return value != null && !value.isBlank();
    }
}

package com.dianping.service.impl;

import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.dianping.VO.CommentVO;
import com.dianping.constant.SystemConstants;
import com.dianping.constant.RedisConstants;
import com.dianping.dto.CreateCommentDTO;
import com.dianping.dto.UserDTO;
import com.dianping.entity.Blog;
import com.dianping.entity.BlogComments;
import com.dianping.entity.User;
import com.dianping.mapper.BlogMapper;
import com.dianping.mapper.BlogCommentsMapper;
import com.dianping.service.BlogCommentsService;
import com.dianping.service.UserService;
import com.dianping.service.BlogCommentsService.LikeResult;
import com.dianping.result.Result;
import com.dianping.utils.UserHolder;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.stereotype.Service;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.RedisCallback;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.redisson.api.RedissonClient;
import org.redisson.api.RLock;
import lombok.extern.slf4j.Slf4j;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;


@Service
@Slf4j
public class BlogCommentsServiceImpl extends ServiceImpl<BlogCommentsMapper, BlogComments> implements BlogCommentsService {

    @Autowired
    private BlogMapper blogMapper;
    @Autowired
    private UserService userService;
    @Autowired
    private StringRedisTemplate stringRedisTemplate;
    @Autowired
    private RedissonClient redissonClient;

    @Override
    @Transactional
    public Result<Long> createComment(Long blogId, CreateCommentDTO request) {
        if (blogId == null || blogId <= 0) {
            return Result.error("非法博客Id");
        }
        UserDTO currentUser = UserHolder.getUser();
        if (currentUser == null || currentUser.getId() == null) {
            return Result.error("请先登录");
        }
        if (request == null || request.getContent() == null) {
            return Result.error("评论内容不能为空");
        }
        String content = request.getContent().trim();
        if (content.isEmpty()) {
            return Result.error("评论内容不能为空");
        }
        if (content.length() > 255) {
            return Result.error("评论内容不能超过255个字符");
        }
        if (blogMapper.selectById(blogId) == null) {
            return Result.error("博客不存在");
        }

        BlogComments comment = new BlogComments()
                .setBlogId(blogId)
                .setUserId(currentUser.getId())
                .setParentId(0L)
                .setAnswerId(0L)
                .setContent(content)
                .setStatus(0)
                .setLiked(0L);
        if (!save(comment)) {
            return Result.error("评论发布失败");
        }

        boolean updated = blogMapper.update(null, new UpdateWrapper<Blog>()
                .eq("id", blogId)//COALESCE是SQL函数，返回第一个不为null的参数，避免null+1还是null
                .setSql("comments = COALESCE(comments, 0) + 1")) > 0;
        if (!updated) {
            throw new IllegalStateException("博客评论数更新失败");
        }
        return Result.success(comment.getId());
    }

    @Override
    public Result<Page<CommentVO>> queryComments(Long blogId, Integer current) {
        if (blogId == null || blogId <= 0) {
            return Result.error("非法博客Id");
        }
        if (current == null || current < 1) {
            return Result.error("页码无效");
        }
        if (blogMapper.selectById(blogId) == null) {
            return Result.error("博客不存在");
        }

        Page<BlogComments> source = new Page<>(current, SystemConstants.MAX_PAGE_SIZE);
        query()
                .eq("blog_id", blogId)
                .eq("parent_id", 0)
                .and(wrapper -> wrapper.eq("status", 0).or().isNull("status"))
                .orderByDesc("create_time")
                .orderByDesc("id")
                .page(source);

        List<BlogComments> comments = source.getRecords();
        List<Long> userIds = comments.stream()
                .map(BlogComments::getUserId)
                .filter(Objects::nonNull)
                .distinct()
                .toList();
        Map<Long, User> users = userIds.isEmpty()
                ? Collections.emptyMap()
                : userService.listByIds(userIds).stream()
                .collect(Collectors.toMap(User::getId, Function.identity(), (left, right) -> left,
                        LinkedHashMap::new));

        UserDTO currentUser = UserHolder.getUser();
        Long userId = currentUser == null ? null : currentUser.getId();

        List<CommentVO> records = comments.stream().map(comment -> {
            CommentVO vo = new CommentVO();
            vo.setId(comment.getId());
            vo.setBlogId(comment.getBlogId());
            vo.setUserId(comment.getUserId());
            vo.setContent(comment.getContent());
            vo.setCreateTime(comment.getCreateTime());
            vo.setUpdateTime(comment.getUpdateTime());
            vo.setLiked(comment.getLiked() == null ? 0 : comment.getLiked());
            User user = users.get(comment.getUserId());
            if (user != null) {
                vo.setUserName(user.getNickName());
                vo.setUserIcon(user.getIcon());
            }
            return vo;
        }).toList();
        fillLikeStates(records, userId);

        Page<CommentVO> resultPage = new Page<>(source.getCurrent(), source.getSize(), source.getTotal());
        resultPage.setRecords(records);
        return Result.success(resultPage);
    }

    @Override
    public Result<LikeResult> toggleCommentLike(Long blogId, Long commentId) {
        if (blogId == null || blogId <= 0) return Result.error("非法博客Id");
        if (commentId == null || commentId <= 0) return Result.error("非法评论Id");
        UserDTO user = UserHolder.getUser();
        if (user == null || user.getId() == null || user.getId() <= 0) return Result.error("请先登录");

        RLock lock = null;
        boolean acquired = false;
        try {
            lock = redissonClient.getLock(RedisConstants.COMMENT_LIKED_LOCK_KEY + commentId + ":" + user.getId());
            acquired = lock.tryLock(1, TimeUnit.SECONDS);
            if (!acquired) return Result.error("操作频繁，请稍后重试");
            BlogComments comment = getById(commentId);
            if (comment == null) return Result.error("评论不存在");
            if (!blogId.equals(comment.getBlogId())) return Result.error("评论不属于该博客");
            if (!Long.valueOf(0).equals(comment.getParentId())
                    || (comment.getStatus() != null && comment.getStatus() != 0)) {
                return Result.error("评论不允许点赞");
            }

            String key = likeKey(commentId);
            Long relations = stringRedisTemplate.opsForSet().size(key);
            if (relations == null) throw new IllegalStateException("未取得点赞关系数量");
            if (comment.getLiked() != null && comment.getLiked() > 0 && relations == 0) {
                return Result.error("评论点赞数据待核对");
            }
            Boolean originalLiked = stringRedisTemplate.opsForSet().isMember(key, user.getId().toString());
            if (originalLiked == null) throw new IllegalStateException("未取得点赞状态");

            // 先更新数据库，再修改 Set。两者部分成功时返回错误，不补偿或重放切换。
            int updated = originalLiked ? baseMapper.decrementLiked(commentId, blogId)
                    : baseMapper.incrementLiked(commentId, blogId);
            if (updated != 1) return Result.error("点赞操作失败，请刷新后重试");
            Long changed = originalLiked ? stringRedisTemplate.opsForSet().remove(key, user.getId().toString())
                    : stringRedisTemplate.opsForSet().add(key, user.getId().toString());
            if (!Long.valueOf(1).equals(changed)) throw new IllegalStateException("点赞关系更新结果异常");
            BlogComments current = getById(commentId);
            if (current == null || current.getLiked() == null) throw new IllegalStateException("未取得更新后的点赞数");
            return Result.success(new LikeResult(current.getLiked(), !originalLiked));
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "点赞服务暂时不可用", interrupted);
        } catch (RuntimeException failure) {
            log.warn("评论点赞失败，评论={}，用户={}；部分写入可能需要核对", commentId, user.getId(), failure);
            throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "点赞服务暂时不可用", failure);
        } finally {
            if (acquired) {
                try { lock.unlock(); }
                catch (RuntimeException failure) { log.warn("释放评论点赞锁失败，评论={}", commentId, failure); }
            }
        }
    }

    /** 仅为兼容旧关系 Set 保留分区键名，不再使用同步 Hash 或队列。 */
    private static String likeKey(Long commentId) {
        return "{" + RedisConstants.COMMENT_LIKE_KEY + ":" + Math.floorMod(commentId, 4) + "}:" + commentId + ":users";
    }

    /** 一页评论的关系读取使用管道；故障时保留数据库数量，禁用点赞按钮。 */
    private void fillLikeStates(List<CommentVO> records, Long userId) {
        records.forEach(vo -> {
            vo.setIsLike(userId == null ? false : null);
            vo.setLikeAvailable(false);
        });
        if (records.isEmpty()) return;
        try {
            List<Object> states = stringRedisTemplate.executePipelined((RedisCallback<Object>) connection -> {
                for (CommentVO vo : records) {
                    byte[] key = likeKey(vo.getId()).getBytes(StandardCharsets.UTF_8);
                    connection.setCommands().sCard(key);
                    if (userId != null) connection.setCommands().sIsMember(key, userId.toString().getBytes(StandardCharsets.UTF_8));
                }
                return null;
            });
            int stride = userId == null ? 1 : 2;
            if (states.size() != records.size() * stride) throw new IllegalStateException("点赞状态返回数量异常");
            for (int i = 0; i < records.size(); i++) {
                CommentVO vo = records.get(i);
                long count = (Long) states.get(i * stride);
                boolean available = !(vo.getLiked() > 0 && count == 0);
                vo.setLikeAvailable(available);
                vo.setIsLike(userId == null ? Boolean.FALSE : available ? (Boolean) states.get(i * stride + 1) : null);
            }
        } catch (RuntimeException failure) {
            records.forEach(vo -> {
                vo.setIsLike(userId == null ? false : null);
                vo.setLikeAvailable(false);
            });
            log.warn("评论点赞状态读取失败，保留评论列表和数据库数量", failure);
        }
    }
}

package com.dianping.service.impl;

import com.dianping.VO.BlogVO;
import com.dianping.constant.RedisConstants;
import com.dianping.constant.SystemConstants;
import com.dianping.dto.UserDTO;
import com.dianping.entity.Blog;
import com.dianping.entity.User;
import com.dianping.feed.FeedTaskRepository;
import com.dianping.mapper.BlogMapper;
import com.dianping.result.Result;
import com.dianping.service.BlogService;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.dianping.service.UserService;
import com.dianping.utils.UserHolder;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import lombok.extern.slf4j.Slf4j;
import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;
import org.springframework.beans.BeanUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.temporal.ChronoUnit;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

@Slf4j
@Service
public class BlogServiceImpl extends ServiceImpl<BlogMapper, Blog> implements BlogService {
    @Autowired
    private UserService userService;
    @Autowired
    private StringRedisTemplate stringRedisTemplate;
    @Autowired
    private RedissonClient redissonClient;
    @Autowired
    private FeedTaskRepository feedTasks;

    @Override
    @Transactional
    public Result<Long> publishBlog(Blog blog) {
        UserDTO user = UserHolder.getUser();
        if (user == null || user.getId() == null) return Result.error("请先登录");
        // 发布 ID、作者、时间和计数均由服务端维护，不能由请求伪造。
        LocalDateTime now = LocalDateTime.now(ZoneOffset.UTC).truncatedTo(ChronoUnit.SECONDS);
        blog.setId(null).setUserId(user.getId()).setCreateTime(now).setUpdateTime(now).setLiked(0).setComments(0);
        if (!save(blog)) throw new IllegalStateException("博客发布失败");
        feedTasks.publish(blog.getId(), user.getId());
        return Result.success(blog.getId());
    }

    @Override
    public Result<BlogVO> queryBlogById(Long blogId) {
        Blog blog = getById(blogId);
        if(blog == null)return Result.error("博客不存在!") ;

        BlogVO blogVO = new BlogVO();
        BeanUtils.copyProperties(blog,blogVO);
        //博客对应的用户
        User user = userService.getById(blog.getUserId());
        if(user == null)return Result.error("用户不存在!");

        //当前用户
        UserDTO currentUser = UserHolder.getUser() ;
        Boolean isLiked = false ;//匿名用户默认是false没点赞就行

        if(currentUser != null){
            isLiked = stringRedisTemplate.opsForSet().isMember(RedisConstants.BLOG_LIKE_KEY + blogId ,
                    currentUser.getId().toString());
        }

        if(isLiked == null)return Result.error("点赞状态获取失败") ;

        blogVO.setIsLike(isLiked);
        blogVO.setName(user.getNickName());
        blogVO.setIcon(user.getIcon());

        return Result.success(blogVO) ;
    }

    @Override
    public Result<Void> likeBlog(Long blogId) {
        if(blogId == null || blogId <= 0)return Result.error("非法博客Id") ;

        Long userId = UserHolder.getUser().getId();
        String likeKey = RedisConstants.BLOG_LIKE_KEY + blogId ;
        RLock lock = redissonClient.getLock(RedisConstants.BLOG_LIKED_LOCK_KEY + blogId
                + ":" + userId);

        try{
            //没抢到锁最多重试1s返回
            if(!lock.tryLock(1, TimeUnit.SECONDS)){
                return Result.error("操作频繁，请稍后再试") ;
            }

            try{
                if(getById(blogId) == null)return Result.error("博客不存在!") ;
                Boolean isLiked = stringRedisTemplate.opsForSet().isMember(likeKey , userId.toString()) ;
                if(isLiked == null){
                    return Result.error("点赞状态查询失败") ;
                }
                boolean updated = isLiked ? update().setSql("liked = liked - 1")
                                                                 .eq("id" , blogId).gt("liked" , 0)
                                                                 .update() :
                        update().setSql("liked = liked + 1").eq("id" , blogId).update() ;

                if(!updated)return Result.error("点赞操作失败") ;

                if(isLiked){
                    stringRedisTemplate.opsForSet().remove(likeKey , userId.toString()) ;
                }else{
                    stringRedisTemplate.opsForSet().add(likeKey , userId.toString()) ;
                }
                return Result.success() ;
            }finally{
                lock.unlock();
            }

        } catch (RuntimeException e) {
            log.error("博客点赞失败,blogId ={} , userId ={}" , blogId , userId ,e) ;
            return Result.error("点赞服务暂时不可用") ;
        }catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return Result.error("点赞操作异常中断") ;
        }
    }


    @Override
    public Result<List<Blog>> pageQueryHotBlog(Integer page) {
        if (page == null || page < 1) {
            return Result.error("页码无效");
        }

        List<Blog> blogs = query()
                .orderByDesc("liked")
                .orderByDesc("id")
                .page(new Page<>(page, SystemConstants.MAX_PAGE_SIZE))
                .getRecords();
        UserDTO currentUser = UserHolder.getUser();
        String currentUserId = currentUser == null || currentUser.getId() == null
                ? null : currentUser.getId().toString();

        for (Blog blog : blogs) {
            User author = userService.getById(blog.getUserId());
            if (author != null) {
                blog.setName(author.getNickName());
                blog.setIcon(author.getIcon());
            }

            if (currentUserId == null) {
                blog.setIsLike(false);
                continue;
            }
            Boolean isLiked = stringRedisTemplate.opsForSet().isMember(
                    RedisConstants.BLOG_LIKE_KEY + blog.getId(), currentUserId);
            if (isLiked == null) {
                return Result.error("点赞状态获取失败");
            }
            blog.setIsLike(isLiked);
        }
        return Result.success(blogs);
    }

    @Override
    public Result<Page<BlogVO>> queryBlogsByUser(Long userId, Integer current) {
        if (userId == null || userId <= 0) {
            return Result.error("用户ID非法");
        }
        if (current == null || current < 1) {
            return Result.error("页码无效");
        }

        User author = userService.getById(userId);
        if (author == null) {
            return Result.error("用户不存在");
        }

        Page<Blog> source = query()
                .eq("user_id", userId)
                .orderByDesc("create_time")
                .orderByDesc("id")
                .page(new Page<>(current, SystemConstants.MAX_PAGE_SIZE));

        UserDTO currentUser = UserHolder.getUser();
        String currentUserId = currentUser == null || currentUser.getId() == null
                ? null : currentUser.getId().toString();
        List<BlogVO> records = new ArrayList<>(source.getRecords().size());
        for (Blog blog : source.getRecords()) {
            BlogVO vo = new BlogVO();
            BeanUtils.copyProperties(blog, vo);
            vo.setName(author.getNickName());
            vo.setIcon(author.getIcon());

            if (currentUserId == null) {
                vo.setIsLike(false);
            } else {
                Boolean isLiked = stringRedisTemplate.opsForSet().isMember(
                        RedisConstants.BLOG_LIKE_KEY + blog.getId(), currentUserId);
                if (isLiked == null) {
                    return Result.error("点赞状态获取失败");
                }
                vo.setIsLike(isLiked);
            }
            records.add(vo);
        }

        Page<BlogVO> resultPage = new Page<>(source.getCurrent(), source.getSize(), source.getTotal());
        resultPage.setRecords(records);
        return Result.success(resultPage);
    }
}

package com.dianping.service.impl;

import com.dianping.VO.CommonFollowVO;
import com.dianping.constant.RedisConstants;
import com.dianping.dto.UserDTO;
import com.dianping.entity.Follow;
import com.dianping.entity.User;
import com.dianping.entity.UserInfo;
import com.dianping.feed.FeedTaskRepository;
import com.dianping.result.Result;
import com.dianping.mapper.FollowMapper;
import com.dianping.service.FollowService;
import com.dianping.service.UserInfoService;
import com.dianping.service.UserService;
import com.dianping.utils.UserHolder;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.data.redis.core.StringRedisTemplate;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * <p>
 *  服务实现类
 * </p>
 *
 * @author 虎哥
 * @since 2021-12-22
 */
@Service
public class FollowServiceImpl extends ServiceImpl<FollowMapper, Follow> implements FollowService {

    @Autowired
    private UserService userService;

    @Autowired
    private UserInfoService userInfoService;

    @Autowired
    private StringRedisTemplate stringRedisTemplate;
    @Autowired
    private FeedTaskRepository feedTasks;

    @Override
    @Transactional
    public Result<Void> follow(Long followUserId, Boolean toFollow) {
        if (followUserId == null || followUserId <= 0) {
            return Result.error("用户ID非法");
        }
        if (toFollow == null) {
            return Result.error("关注状态不能为空");
        }
        UserDTO currentUser = UserHolder.getUser();
        if (currentUser == null || currentUser.getId() == null) {
            return Result.error("请先登录");
        }
        Long userId = currentUser.getId();
        if (userId.equals(followUserId)) {
            return Result.error("不能关注自己");
        }
        User target = userService.getById(followUserId);
        if (target == null) {
            return Result.error("用户不存在");
        }
        //查询数据库中是否已有关注关系
        boolean exists = lambdaQuery()
                .eq(Follow::getUserId, userId)
                .eq(Follow::getFollowUserId, followUserId)
                .exists();

        //toFollow为true就表明本次要执行关注操作，为false就表明本次要执行取关
        if (toFollow) {
            if (exists) {
                syncFollowSet(userId, followUserId);
                return Result.success();
            }
            try {//保存关注关系到follow表
                if (!save(new Follow().setUserId(userId).setFollowUserId(followUserId))) {
                    return Result.error("关注失败");
                }
            } catch (DataIntegrityViolationException ex) {
                // A concurrent request created the unique relation first.
                syncFollowSet(userId, followUserId);
                return Result.success();
            }//再接着修改用户详情
            UserInfo currentInfo = userInfoService.getOrCreate(userId);
            UserInfo targetInfo = userInfoService.getOrCreate(followUserId);
            if (currentInfo == null
                    || targetInfo == null
                    || !increment(userId, "followee")
                    || !increment(followUserId, "fans")) {
                throw new IllegalStateException("关注计数更新失败");
            }
            syncFollowSet(userId, followUserId);
            feedTasks.relationship(userId, followUserId, true);
            return Result.success();
        }

        if (!exists) {
            stringRedisTemplate.opsForSet().remove(followSetKey(userId), String.valueOf(followUserId));
            return Result.success();
        }
        boolean removed = remove(lambdaQuery()
                .eq(Follow::getUserId, userId)
                .eq(Follow::getFollowUserId, followUserId)
                .getWrapper());
        if (!removed) {
            return Result.error("取消关注失败");
        }
        UserInfo currentInfo = userInfoService.getOrCreate(userId);
        UserInfo targetInfo = userInfoService.getOrCreate(followUserId);
        if (currentInfo == null
                || targetInfo == null
                || !decrement(userId, "followee")
                || !decrement(followUserId, "fans")) {
            throw new IllegalStateException("关注计数更新失败");
        }
        stringRedisTemplate.opsForSet().remove(followSetKey(userId), String.valueOf(followUserId));
        feedTasks.relationship(userId, followUserId, false);
        return Result.success();
    }

    /**
     * 查询共同关注
     * @param followUserId
     * @return
     */
    @Override
    public Result<List<CommonFollowVO>> queryCommonFollows(Long followUserId) {
        if (followUserId == null || followUserId <= 0) {
            return Result.error("用户ID非法");
        }
        UserDTO currentUser = UserHolder.getUser();
        if (currentUser == null || currentUser.getId() == null) {
            return Result.error("请先登录");
        }
        Long currentUserId = currentUser.getId();
        if (userService.getById(followUserId) == null) {
            return Result.error("用户不存在");
        }
        if (currentUserId.equals(followUserId)) {
            return Result.success(Collections.emptyList());
        }

        ensureFollowSet(currentUserId);
        ensureFollowSet(followUserId);

        Set<String> commonIds = stringRedisTemplate.opsForSet().intersect(
                followSetKey(currentUserId), followSetKey(followUserId));
        if (commonIds == null || commonIds.isEmpty()) {
            return Result.success(Collections.emptyList());
        }

        List<Long> userIds = commonIds.stream()
                .map(this::parseUserId)
                .filter(java.util.Objects::nonNull)
                .toList();
        if (userIds.isEmpty()) {
            return Result.success(Collections.emptyList());
        }
        List<User> users = userService.listByIds(userIds);
        List<CommonFollowVO> result = new ArrayList<>(users.size());
        for (User user : users) {
            CommonFollowVO vo = new CommonFollowVO();
            vo.setId(user.getId());
            vo.setNickName(user.getNickName());
            vo.setIcon(user.getIcon());
            result.add(vo);
        }
        return Result.success(result);
    }

    // Redis 集合存在时直接走缓存；只有缓存缺失时才从数据库重建。
    private void ensureFollowSet(Long userId) {
        String key = followSetKey(userId);
        if (stringRedisTemplate.hasKey(key)) {
            return;
        }
        rebuildFollowSet(key, loadFollowIds(userId));
    }

    private List<String> loadFollowIds(Long userId) {
        return lambdaQuery()
                .eq(Follow::getUserId, userId)
                .select(Follow::getFollowUserId)
                .list()
                .stream()
                .map(Follow::getFollowUserId)
                .filter(java.util.Objects::nonNull)
                .map(String::valueOf)
                .toList();
    }

    private void rebuildFollowSet(String key, List<String> followIds) {
        stringRedisTemplate.delete(key);
        if (!followIds.isEmpty()) {
            stringRedisTemplate.opsForSet().add(key, followIds.toArray(String[]::new));
        }
    }

    // 关注关系变更后重建完整集合，避免冷缓存只写入本次目标而丢失历史关注。
    private void syncFollowSet(Long userId, Long ignoredFollowUserId) {
        rebuildFollowSet(followSetKey(userId), loadFollowIds(userId));
    }
    //统一生成redis的key
    private String followSetKey(Long userId) {
        return RedisConstants.FOLLOW_USER_KEY + userId;
    }
    //把redis里String类型的id转成Long类型
    private Long parseUserId(String value) {
        try {
            return Long.valueOf(value);
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    //true：已经关注，false：尚未关注
    @Override
    public Result<Boolean> isFollow(Long followUserId) {
        if (followUserId == null || followUserId <= 0) {
            return Result.error("用户ID非法");
        }
        UserDTO currentUser = UserHolder.getUser();
        if (currentUser == null || currentUser.getId() == null) {
            return Result.error("请先登录");
        }
        if (userService.getById(followUserId) == null) {
            return Result.error("用户不存在");
        }
        boolean exists = lambdaQuery()
                .eq(Follow::getUserId, currentUser.getId())
                .eq(Follow::getFollowUserId, followUserId)
                .exists();
        return Result.success(exists);
    }

    private boolean increment(Long userId, String field) {
        return userInfoService.update()
                .setSql(field + " = COALESCE(" + field + ", 0) + 1")
                .eq("user_id", userId)
                .update();
    }

    private boolean decrement(Long userId, String field) {
        return userInfoService.update()
                .setSql(field + " = GREATEST(COALESCE(" + field + ", 0) - 1, 0)")
                .eq("user_id", userId)
                .update();
    }

}

