    //构造器注入
    public UserServiceImpl(StringRedisTemplate stringRedisTemplate,
                           TokenService tokenService, PasswordEncoder passwordEncoder,
                           UserInfoService userInfoService) {
        this.stringRedisTemplate = stringRedisTemplate;
        this.tokenService = tokenService ;
        this.passwordEncoder = passwordEncoder;
        this.userInfoService = userInfoService;
    }

    @Override
    public Result<Void> sendCodeWhenLogin(String phone) {
        //先校验手机号
        //如果格式不对就直接return
        if(RegexUtils.isPhoneInvalid(phone)){
            return Result.error("手机号格式错误！") ;
        }

        //顺便校验用户是否存在
        User user = getOne(
                Wrappers.<User>lambdaQuery()
                        .eq(User::getPhone, phone)
        );

        if (user == null) {
            return Result.error("用户不存在，请先注册");
        }
        if (!acquireCodeSendPermit("login:", phone)) {
            return Result.error("验证码请求过于频繁，请稍后再试");
        }
        // 格式正确就生成验证码并保存到 Redis
        String code = randomDigits(6);
        log.debug("验证码已生成：{}" , code) ;
        stringRedisTemplate.opsForValue().set(
                RedisConstants.LOGIN_CODE_KEY + phone,
                code,
                RedisConstants.CODE_TTL,
                TimeUnit.MINUTES);
        log.debug("登录验证码已生成并写入 Redis");
        return Result.success() ;
    }

    @Override
    public Result<Void> sendCodeWhenRegister(String phone){
        //先校验手机号
        //如果格式不对就直接return
        if(RegexUtils.isPhoneInvalid(phone)){
            return Result.error("手机号格式错误！") ;
        }

        boolean exists = lambdaQuery()
                .eq(User::getPhone, phone)
                .exists();
        if (exists) {
            return Result.error("手机号已注册");
        }
        if (!acquireCodeSendPermit("register:", phone)) {
            return Result.error("验证码请求过于频繁，请稍后再试");
        }

        // 格式正确就生成验证码并保存到 Redis
        String code = randomDigits(6);
        log.debug("验证码已生成：{}" , code) ;
        stringRedisTemplate.opsForValue().set(
                RedisConstants.REGISTER_CODE_KEY + phone,
                code,
                RedisConstants.CODE_TTL,
                TimeUnit.MINUTES);
        log.debug("注册验证码已生成并写入 Redis");
        return Result.success() ;
    }

    @Override
    public Result<UserVO> queryUserById(Long userId) {
        if (userId == null || userId <= 0) {
            return Result.error("用户ID非法");
        }
        User user = getById(userId);
        if (user == null) {
            return Result.error("用户不存在");
        }

        UserInfo info = userInfoService.getOrCreate(userId);
        if (info == null) {
            return Result.error("用户详情获取失败");
        }

        UserVO vo = new UserVO();
        BeanUtils.copyProperties(user, vo);
        vo.setCity(info.getCity());
        vo.setIntroduce(info.getIntroduce());
        vo.setFans(info.getFans());
        vo.setFollowee(info.getFollowee());
        return Result.success(vo);
    }

    @Override
    public Result<TokenVO> login(LoginDTO loginDTO) {
        String loginType = loginDTO.getLoginType();
        // 校验手机号
        if (RegexUtils.isPhoneInvalid(loginDTO.getPhone())) {
            return Result.error("手机号格式错误");
        }
        //校验登录类型，避免无效请求仍然查询数据库
        boolean codeLogin = Objects.equals(
                loginType,
                SystemConstants.CODE_LOGIN
        );

        boolean passwordLogin = Objects.equals(
                loginType,
                SystemConstants.PASSWORD_LOGIN
        );

        if (!codeLogin && !passwordLogin) {
            return Result.error("错误的登录类型");
        }

        //利用Mybatis-plus的IService接口提供的getOne方法快速根据phone查询用户
        User user = getOne(Wrappers.<User>lambdaQuery()
                .eq(User::getPhone, loginDTO.getPhone()));
        if(user == null )return Result.error("用户不存在，请先注册") ;

        if(codeLogin) return loginByCode(loginDTO , user) ;

        return loginByPassword(loginDTO ,user) ;

    }

    @Override
    @Transactional
    public Result<Void> register(RegisterDTO registerDTO) {
        String phone = registerDTO.getPhone();

        // 1.确认两次密码一致
        if (!Objects.equals(
                registerDTO.getPassword(),
                registerDTO.getConfirmPassword())) {
            return Result.error("两次输入的密码不一致");
        }

        // 2.判断手机号是否已经注册
        boolean exists = lambdaQuery()
                .eq(User::getPhone, phone)
                .exists();

        if (exists) {
            return Result.error("手机号已注册");
        }

        // 3.读取注册验证码
        String codeKey =
                RedisConstants.REGISTER_CODE_KEY + phone;

        String storedCode = stringRedisTemplate
                .opsForValue()
                .get(codeKey);

        if (storedCode == null) {
            return Result.error("验证码已失效");
        }

        if (!Objects.equals(
                storedCode,
                registerDTO.getVerifyCode())) {
            return Result.error("验证码错误");
        }

        if (!consumeCode(codeKey, registerDTO.getVerifyCode())) {
            return Result.error("验证码已失效");
        }

        // 4.创建用户
        User user = new User();
        user.setPhone(phone);
        user.setPassword(
                passwordEncoder.encode(
                        registerDTO.getPassword()
                )
        );
        user.setNickName(
                SystemConstants.USER_NICK_NAME_PREFIX
                        + randomAlphaNumeric(10)
        );

        // 5.保存数据库
        save(user);
        userInfoService.getOrCreate(user.getId());

        return Result.success();
    }

    private Result<TokenVO> loginByCode(LoginDTO loginDTO, User user) {
        //从redis里查询验证码
        String storedCode = stringRedisTemplate.opsForValue()
                .get(RedisConstants.LOGIN_CODE_KEY + loginDTO.getPhone()) ;
        if(storedCode != null){

            if(Objects.equals(storedCode, loginDTO.getVerifyCode())){
                String codeKey = RedisConstants.LOGIN_CODE_KEY + loginDTO.getPhone();
                if (!consumeCode(codeKey, loginDTO.getVerifyCode())) {
                    return Result.error("验证码已失效");
                }
                return Result.success(tokenService.issue(String.valueOf(user.getId()))) ;
            }

            else {
                return Result.error("验证码错误") ;
            }
        }

        else{
            return Result.error("验证码已失效") ;
        }
        }

    private boolean consumeCode(String codeKey, String expectedCode) {
        Long consumed = stringRedisTemplate.execute(
                CONSUME_CODE_SCRIPT,
                Collections.singletonList(codeKey),
                expectedCode
        );
        return Long.valueOf(1L).equals(consumed);
    }

    private boolean acquireCodeSendPermit(String purpose, String phone) {
        Boolean acquired = stringRedisTemplate.opsForValue().setIfAbsent(
                RedisConstants.CODE_SEND_COOLDOWN_KEY + purpose + phone,
                "1",
                RedisConstants.CODE_SEND_COOLDOWN_TTL,
                TimeUnit.SECONDS
        );
        return Boolean.TRUE.equals(acquired);
    }

        private Result<TokenVO> loginByPassword(LoginDTO loginDTO, User user) {
            String rawPassword = loginDTO.getPassword();
            if(rawPassword == null || rawPassword.isEmpty()){
                return Result.error("密码不能为空") ;
            }
            boolean matched = passwordEncoder.matches(rawPassword,
                    user.getPassword());
            if (!matched) {
                return Result.error("用户名或密码错误");
            }
            return Result.success(tokenService.issue(String.valueOf(user.getId())));

        }
}

package com.dianping.service.impl;

import com.dianping.VO.VisitStatsVO;
import com.dianping.dto.VisitRequestDTO;
import com.dianping.exception.VisitStatsException;
import com.dianping.mapper.BlogMapper;
import com.dianping.mapper.ShopMapper;
import com.dianping.service.VisitStatsService;
import org.springframework.core.io.ClassPathResource;
import org.springframework.dao.DataAccessResourceFailureException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

@Service
public class VisitStatsServiceImpl implements VisitStatsService {
    private static final Pattern UUID_PATTERN = Pattern.compile(
            "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");
    private static final DefaultRedisScript<Long> RECORD = new DefaultRedisScript<>();
    static {
        RECORD.setLocation(new ClassPathResource("lua/record-visit.lua"));
        RECORD.setResultType(Long.class);
    }
    private final StringRedisTemplate redis;
    private final BlogMapper blogs;
    private final ShopMapper shops;

    public VisitStatsServiceImpl(StringRedisTemplate redis, BlogMapper blogs, ShopMapper shops) {
        this.redis = redis;
        this.blogs = blogs;
        this.shops = shops;
    }

    @Override
    public VisitStatsVO recordBlog(Long id, VisitRequestDTO event) {
        validate(id, event);
        if (blogs.selectById(id) == null) throw new VisitStatsException(HttpStatus.NOT_FOUND, "博客不存在");
        return record("blog", id, "pv", event);
    }

    @Override
    public VisitStatsVO recordShop(Long id, VisitRequestDTO event) {
        validate(id, event);
        if (shops.selectById(id) == null) throw new VisitStatsException(HttpStatus.NOT_FOUND, "店铺不存在");
        return record("shop", id, "uv", event);
    }

    private VisitStatsVO record(String resource, long id, String metric, VisitRequestDTO event) {
        String prefix = "stats:{" + resource + ":" + id + "}:";
        String visitor = event.visitorId().toLowerCase(Locale.ROOT);
        String eventId = event.eventId().toLowerCase(Locale.ROOT);
        // 同资源的键放入同一 Redis Cluster 槽，计数与事件去重由脚本原子执行。
        Long count = redis.execute(RECORD, List.of(prefix + metric,
                prefix + "event:" + visitor + ":" + eventId, prefix + "rate:" + visitor),
                metric, visitor, "30", "60", "86400");
        if (count == null) throw new DataAccessResourceFailureException("Redis 未确认访问统计结果");
        if (count == -1) throw new VisitStatsException(HttpStatus.TOO_MANY_REQUESTS, "访问上报过于频繁，请稍后再试");
        if (count < 0) throw new DataAccessResourceFailureException("Redis 返回无效访问统计结果");
        return new VisitStatsVO(count);
    }

    private static void validate(Long id, VisitRequestDTO event) {
        if (id == null || id <= 0 || event == null || !isUuid(event.visitorId()) || !isUuid(event.eventId())) {
            throw new VisitStatsException(HttpStatus.BAD_REQUEST, "资源 ID 或访客、事件标识无效");
        }
    }

    private static boolean isUuid(String value) { return value != null && UUID_PATTERN.matcher(value).matches(); }
}

package com.dianping.service.impl;

import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.dianping.entity.VoucherOrder;
import com.dianping.mapper.VoucherOrderMapper;
import com.dianping.service.SeckillVoucherService;
import com.dianping.service.VoucherOrderPersistService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class VoucherOrderPersistServiceImpl extends ServiceImpl<VoucherOrderMapper, VoucherOrder>
        implements VoucherOrderPersistService {

    @Autowired
    SeckillVoucherService seckillVoucherService;

    @Override
    @Transactional
    public  void createVoucherOrder(VoucherOrder voucherOrder) {
        Long userId = voucherOrder.getUserId();
        // 5.1.查询订单 幂等设计，不重复扣库存
        long count = query().eq("user_id", userId)
                .eq("voucher_id", voucherOrder.getVoucherId()).count();
        // 5.2.判断是否存在
        if (count > 0) {
            // 用户已经购买过了
            log.error("用户已经购买过了");
            return ;
        }

        // 6.扣减库存
        boolean success = seckillVoucherService.update()
                .setSql("stock = stock - 1")
                .eq("voucher_id", voucherOrder.getVoucherId())
                .gt("stock", 0)
                .update();
        if (!success) {
            // 扣减失败
            throw new IllegalStateException("库存数据不足!") ;
        }
        save(voucherOrder);

    }
}

package com.dianping.service.impl;

import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.dianping.constant.RedisConstants;
import com.dianping.dto.UserDTO;
import com.dianping.entity.SeckillVoucher;
import com.dianping.entity.Voucher;
import com.dianping.entity.VoucherOrder;
import com.dianping.mapper.VoucherMapper;
import com.dianping.mapper.VoucherOrderMapper;
import com.dianping.result.Result;
import com.dianping.service.SeckillVoucherService;
import com.dianping.service.VoucherOrderPersistService;
import com.dianping.service.VoucherOrderService;
import com.dianping.utils.RedisIdWorker;
import com.dianping.utils.SimpleRedisLock;
import com.dianping.utils.UserHolder;

import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;

import org.springframework.aop.framework.AopContext;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.connection.stream.*;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.*;




import java.time.Duration;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;
import java.util.UUID;
import java.util.concurrent.*;



@Service
public class VoucherOrderServiceImpl extends ServiceImpl<VoucherOrderMapper, VoucherOrder> implements VoucherOrderService {

    @Autowired
    private RedisIdWorker redisIdWorker;
    @Autowired
    private StringRedisTemplate stringRedisTemplate;
    @Autowired
    private VoucherOrderPersistService voucherOrderPersistService;

    private static final String ORDER_GROUP = "g1";
    private static final int CLAIM_BATCH_SIZE = 10;
    private static final int MAX_CLAIM_PAGES = 5;
    // 实例使用独立身份；重启后由 XAUTOCLAIM 恢复旧实例的超时 Pending。
    private final String consumerName = "orders-" + UUID.randomUUID();
    private String pendingCursor = "0-0";

    @Value("${seckill.stream.claim-min-idle-ms:60000}")
    private long claimMinIdleMillis = 60_000;
    @Value("${seckill.stream.recovery-interval-ms:10000}")
    private long recoveryIntervalMillis = 10_000;

    // Redis 6.2+；通过脚本接口调用命令，沿用 StringRedisTemplate 的嵌套结果反序列化。
    private static final DefaultRedisScript<List> CLAIM_SCRIPT = new DefaultRedisScript<>(
            "return redis.call('XAUTOCLAIM', KEYS[1], ARGV[1], ARGV[2], ARGV[3], ARGV[4], 'COUNT', ARGV[5])",
            List.class);


    private static final DefaultRedisScript<Long> SECKILL_SCRIPT ;
    static{
        SECKILL_SCRIPT = new DefaultRedisScript<>();
        SECKILL_SCRIPT.setLocation(new ClassPathResource("seckill.lua")) ;
        SECKILL_SCRIPT.setResultType(Long.class);
    }

    //异步处理线程池   创立了一个单线程线程池，专门用于处理秒杀订单
    //订单按顺序处理，同一个JVM内不会有多个线程同时写订单 但数据库落库串行执行，吞吐量受单个消费者限制
    // 由当前 Service 实例负责启动和关闭
    private final ExecutorService orderExecutor =
            Executors.newSingleThreadExecutor();
    // volatile 保证后台线程能及时看到停止信号
    private volatile boolean running = true;


    //在类初始化之后执行
    @PostConstruct
    private void init() {
        if (claimMinIdleMillis <= 0 || recoveryIntervalMillis <= 0) {
            throw new IllegalArgumentException("Stream 接管空闲时间和扫描间隔必须大于 0");
        }
    //向线程池提交一个长期运行的消费者任务
        orderExecutor.submit(new VoucherOrderHandler());
    }

    @PreDestroy
    public void destroy() {
        // 通知消费者：当前这条处理结束后，不再开始下一轮
        running = false;

        // 不再接收新任务，但不会中断正在执行的任务
        orderExecutor.shutdown();

        try {
            // 给当前订单处理、事务提交和 ACK 留出时间
            if (!orderExecutor.awaitTermination(10, TimeUnit.SECONDS)) {
                log.warn("订单消费者未在规定时间内退出，请求中断");

                // 向正在运行的任务发出中断请求
                orderExecutor.shutdownNow();

                if (!orderExecutor.awaitTermination(2, TimeUnit.SECONDS)) {
                    log.warn("订单消费者仍未退出，请检查 Redis 或数据库调用超时");
                }
            }
        } catch (InterruptedException e) {
            orderExecutor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private boolean shouldRun() {
        return running && !Thread.currentThread().isInterrupted();
    }

    // 新消息与超时 Pending 共用消费线程，避免恢复任务与自身并发落库。
    private class VoucherOrderHandler implements Runnable {

        @Override
        public void run() {
            long lastRecoveryNanos = 0;
            boolean firstPass = true;
            while (shouldRun()) {
                try {
                    // 启动即扫描，之后即使没有新消息或异常也定期扫描。
                    long now = System.nanoTime();
                    if (firstPass || now - lastRecoveryNanos >= TimeUnit.MILLISECONDS.toNanos(recoveryIntervalMillis)) {
                        firstPass = false;
                        lastRecoveryNanos = now;
                        try {
                            handlePendingList();
                        } catch (Exception e) {
                            if (!shouldRun()) {
                                return;
                            }
                            log.error("接管 Pending 失败，下个扫描周期重试", e);
                        }
                    }
                    if (!shouldRun()) {
                        return;
                    }
                    //读取消息队列中的订单信息
                    List<MapRecord<String , Object , Object>> list = stringRedisTemplate
                            .opsForStream().read(
                                    Consumer.from(ORDER_GROUP, consumerName),
                                    StreamReadOptions.empty()
                                            .count(1).block(Duration.ofSeconds(2)) ,
                                    StreamOffset.create(RedisConstants.SECKILL_STREAM, ReadOffset.lastConsumed())
                            ) ;
                    //判断订单消息是否为空
                    if(list == null || list.isEmpty()){
                        continue ;//直接开始下一次读取
                    }
                    MapRecord<String , Object , Object> record = list.get(0) ;
                    processOrder(record.getId(), record.getValue());
                } catch (Exception e) {
                    // 如果正在关闭，就结束任务，不再启动重试
                    if (!shouldRun()) {
                        return;
                    }

                    log.error("读取或处理订单异常，未确认消息将由定期扫描恢复", e);
                    if (!pauseAfterFailure()) {
                        return;
                    }
                }
            }
        }
    }

    // 接管组内任意消费者（包括自己）长时间未确认的消息。
    // 限制每轮页数并保留游标，避免大量 Pending 或坏消息饿死新订单。
    private void handlePendingList() {
        for (int page = 0; page < MAX_CLAIM_PAGES && shouldRun(); page++) {
            List<?> response = stringRedisTemplate.execute(
                    CLAIM_SCRIPT, List.of(RedisConstants.SECKILL_STREAM),
                    ORDER_GROUP, consumerName, String.valueOf(claimMinIdleMillis),
                    pendingCursor, String.valueOf(CLAIM_BATCH_SIZE));
            if (response == null || response.size() < 2) {
                throw new IllegalStateException("XAUTOCLAIM 未返回有效扫描结果");
            }
            pendingCursor = response.get(0).toString();
            List<?> entries = (List<?>) response.get(1);
            for (Object entry : entries) {
                if (!shouldRun()) {
                    // 已接管但未处理的消息仍在 PEL，后续实例可再次接管。
                    return;
                }
                List<?> message = (List<?>) entry;
                RecordId messageId = RecordId.of(message.get(0).toString());
                try {
                    List<?> fields = (List<?>) message.get(1);
                    Map<Object, Object> value = new LinkedHashMap<>();
                    for (int i = 0; i < fields.size(); i += 2) {
                        value.put(fields.get(i), fields.get(i + 1));
                    }
                    processOrder(messageId, value);
                } catch (Exception e) {
                    if (!shouldRun()) {
                        return;
                    }
                    // 不 ACK，达到空闲阈值后再试；本轮继续处理后续消息。
                    log.error("接管订单处理失败，messageId=" + messageId, e);
                }
            }
            // Redis 7+ 会额外返回已被删除/裁剪、无法恢复正文的消息 ID。
            if (response.size() > 2 && response.get(2) instanceof List<?> deleted && !deleted.isEmpty()) {
                log.warn("Pending 对应的 Stream 消息已被删除，需要核对订单: " + deleted);
            }
            if ("0-0".equals(pendingCursor)) {
                return;
            }
            // 即使 entries 为空，游标非 0-0 也不能提前结束扫描。
        }
    }

    private void processOrder(RecordId messageId, Map<Object, Object> value) {
        VoucherOrder order = new VoucherOrder();
        order.setId(readOrderField(value, "orderId"));
        order.setUserId(readOrderField(value, "userId"));
        order.setVoucherId(readOrderField(value, "voucherId"));
        // 独立 Service 返回时事务已经提交，之后才确认消息。
        voucherOrderPersistService.createVoucherOrder(order);
        stringRedisTemplate.opsForStream().acknowledge(
                RedisConstants.SECKILL_STREAM, ORDER_GROUP, messageId);
    }

    private Long readOrderField(Map<Object, Object> value, String field) {
        Object raw = value.get(field);
        if (raw == null) {
            throw new IllegalArgumentException("订单消息缺少字段: " + field);
        }
        return Long.valueOf(raw.toString());
    }

    private boolean pauseAfterFailure() {
        try {
            Thread.sleep(1000);
            return shouldRun();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

        @Override
        public Result<Long> seckillVoucher(Long voucherId) {
            //用户id
            Long userId = UserHolder.getUser().getId();
            //订单id
            Long orderId = redisIdWorker.nextId("order");
            // 执行lua脚本
            Long result = stringRedisTemplate.execute(
                    SECKILL_SCRIPT,
                    Arrays.asList(RedisConstants.SECKILL_STOCK_KEY+voucherId,
                            RedisConstants.SECKILL_USER_KEY+voucherId,
                            RedisConstants.SECKILL_STREAM),
                    userId.toString() , voucherId.toString() , orderId.toString()
            );
            int r = result.intValue();
            // 判断结果是否为0
            if (r != 0) {
                // 不为0 ，代表没有购买资格
                return Result.error(r == 1 ? "库存不足" : "不能重复下单");
            }
            //返回订单id
            return Result.success(orderId);
