    private final UserService users = mock(UserService.class);
    private final FeedProperties properties = new FeedProperties();
    private final FeedService service = new FeedService(repository, cache, properties, users);
    private long time;

    @BeforeEach
    void setup() {
        properties.setPageSize(2); properties.setBatchSize(2);
        UserDTO user = new UserDTO(); user.setId(5L); UserHolder.saveUser(user);
        time = System.currentTimeMillis() / 1000 * 1000 - 10000;
        when(repository.authors(5, 1000)).thenReturn(List.of(new FeedRepository.Author(1, false), new FeedRepository.Author(2, true)));
        when(cache.ready(eq(5L), anyString())).thenReturn(true);
        when(users.listByIds(anyCollection())).thenReturn(List.of(new User().setId(1L).setNickName("普通作者")));
    }

    @AfterEach void cleanup() { UserHolder.removeUser(); }
    private Blog blog(long id, long author) { return new Blog().setId(id).setUserId(author).setCreateTime(FeedTimeline.time(time)); }

    @Test
    void fillsPagePastDeletedAndUnfollowedCandidatesAndMergesHotAuthor() {
        when(cache.candidates(eq(5L), anyLong(), anyLong(), eq(0L), eq(2))).thenReturn(List.of(301L, 302L));
        when(cache.candidates(eq(5L), anyLong(), anyLong(), eq(2L), eq(2))).thenReturn(List.of(9L));
        when(repository.blogByIds(List.of(301L, 302L))).thenReturn(List.of(blog(301, 99)));
        when(repository.blogByIds(List.of(9L))).thenReturn(List.of(blog(9, 1)));
        when(repository.recent(eq(List.of(2L)), any(), any(), eq(2))).thenReturn(List.of(blog(80, 2)));

        var result = service.read(time + 1000, 0);
        assertThat(result.getCode()).isEqualTo(1);
        assertThat(result.getData().getList()).extracting(item -> ((Blog) item).getId()).containsExactly(9L, 80L);
        assertThat(((Blog) result.getData().getList().get(0)).getName()).isEqualTo("普通作者");
    }

    @Test
    void redisFailureFallsBackToBothOrdinaryAndHotDatabaseBlogs() {
        when(cache.ready(eq(5L), anyString())).thenThrow(new IllegalStateException("redis offline"));
        when(repository.recent(eq(List.of(1L)), any(), any(), eq(2))).thenReturn(List.of(blog(9, 1)));
        when(repository.recent(eq(List.of(2L)), any(), any(), eq(2))).thenReturn(List.of(blog(80, 2)));
        assertThat(service.read(time + 1000, 0).getData().getList()).hasSize(2);
    }

    @Test
    void databaseFailureIsAnErrorNotAnEmptyFeed() {
        when(repository.authors(5, 1000)).thenThrow(new IllegalStateException("database offline"));
        assertThat(service.read(time, 0).getCode()).isZero();
    }

    @Test
    void missingOrChangedOrdinaryAuthorSignatureBackfillsHistoryBeforeReading() {
        when(cache.ready(eq(5L), anyString())).thenReturn(false);
        when(cache.beginBuild(5)).thenReturn("build-token");
        when(repository.history(eq(List.of(1L)), any(), eq(0L), eq(2))).thenReturn(List.of(blog(9, 1)));
        service.read(time + 1000, 0);
        verify(cache).add(eq(5L), argThat(blogs -> blogs.size() == 1 && blogs.get(0).getId() == 9), anyLong());
        verify(cache).complete(5, "30:[1]", "build-token");
    }

    @Test
    void invalidCursorOrAnonymousRequestDoesNotAccessStorage() {
        assertThat(service.read(time, -1).getCode()).isZero();
        UserHolder.removeUser();
        assertThat(service.read(time, 0).getCode()).isZero();
        verifyNoInteractions(repository, cache);
    }
}

package com.dianping.feed;

import com.dianping.dto.ScrollResult;
import com.dianping.entity.Blog;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

class FeedTimelineTest {
    private Blog blog(long id, long time) { return new Blog().setId(id).setCreateTime(FeedTimeline.time(time)); }

    @Test
    void mergedSameSecondPagesAreLexicographicDeduplicatedAndNeverSkipStaticItems() {
        List<Blog> merged = List.of(blog(10, 10000), blog(9, 10000), blog(80, 10000),
                blog(9, 10000), blog(2, 10000), blog(99, 9000), blog(77, 8000));
        long cursor = 10000;
        int offset = 0;
        List<Long> ids = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            ScrollResult page = FeedTimeline.page(merged, cursor, offset, 2, 8500);
            for (Object item : page.getList()) ids.add(((Blog) item).getId());
            cursor = page.getMinTime(); offset = page.getOffset();
            if (page.getList().isEmpty()) break;
        }
        assertThat(ids).containsExactly(9L, 80L, 2L, 10L, 99L);
    }

    @Test
    void offsetAccumulatesOnlyWhenNextPageEndsAtTheSameTimestamp() {
        List<Blog> merged = List.of(blog(9, 10000), blog(8, 10000), blog(7, 10000), blog(6, 9000));
        ScrollResult sameTime = FeedTimeline.page(merged, 10000, 2, 1, 0);
        assertThat(sameTime.getOffset()).isEqualTo(3);
        ScrollResult older = FeedTimeline.page(merged, 10000, 3, 1, 0);
        assertThat(older.getMinTime()).isEqualTo(9000);
        assertThat(older.getOffset()).isEqualTo(1);
    }
}

package com.dianping.security;

import com.dianping.VO.TokenVO;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ValueOperations;

import java.time.Duration;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class TokenServiceTest {

    private JwtUtils jwtUtils;
    private ValueOperations<String, String> values;
    private TokenService service;

    @BeforeEach
    @SuppressWarnings("unchecked")
    void setUp() {
        jwtUtils = mock(JwtUtils.class);
        JwtProperties properties = new JwtProperties();
        properties.setAccessTtl(Duration.ofMinutes(15));
        properties.setRefreshTtl(Duration.ofDays(7));
        StringRedisTemplate redisTemplate = mock(StringRedisTemplate.class);
        values = mock(ValueOperations.class);
        when(redisTemplate.opsForValue()).thenReturn(values);
        service = new TokenService(jwtUtils, properties, redisTemplate);
    }

    @Test
    void refreshConsumesOldRegistrationAndRegistersRotatedToken() {
        Claims oldClaims = mock(Claims.class);
        when(oldClaims.getId()).thenReturn("old-jti");
        when(oldClaims.getSubject()).thenReturn("42");
        when(jwtUtils.parseRefreshToken("old-refresh")).thenReturn(oldClaims);
        when(values.getAndDelete("auth:refresh:old-jti")).thenReturn("42");

        Claims newClaims = mock(Claims.class);
        when(newClaims.getId()).thenReturn("new-jti");
        when(jwtUtils.generateAccessToken("42")).thenReturn("new-access");
        when(jwtUtils.generateRefreshToken("42")).thenReturn("new-refresh");
        when(jwtUtils.parseRefreshToken("new-refresh")).thenReturn(newClaims);

        TokenVO refreshed = service.refresh("old-refresh");

        assertThat(refreshed.getAccessToken()).isEqualTo("new-access");
        assertThat(refreshed.getRefreshToken()).isEqualTo("new-refresh");
        assertThat(refreshed.getAccessTtl()).isEqualTo(900L);
        verify(values).set("auth:refresh:new-jti", "42", Duration.ofDays(7));
    }

    @Test
    void alreadyConsumedRefreshTokenCannotBeReplayed() {
        Claims claims = mock(Claims.class);
        when(claims.getId()).thenReturn("used-jti");
        when(jwtUtils.parseRefreshToken("used-refresh")).thenReturn(claims);
        when(values.getAndDelete("auth:refresh:used-jti")).thenReturn(null);

        assertThatThrownBy(() -> service.refresh("used-refresh"))
                .isInstanceOf(JwtException.class)
                .hasMessageContaining("已失效");
    }
}

package com.dianping.service;

import com.dianping.dto.UserDTO;
import com.dianping.service.impl.SignServiceImpl;
import com.dianping.utils.UserHolder;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.core.StringRedisTemplate;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.UUID;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.IntStream;

import static org.assertj.core.api.Assertions.assertThat;

// Opt in only with an isolated local Redis, never the application's Redis.
@EnabledIfSystemProperty(named = "signin.redis.port", matches = "[0-9]+")
class SignServiceRedisTest {
    @Test
    void realRedisPreservesBitOrderMonthLengthsAndConcurrentIdempotency() throws Exception {
        int port = Integer.parseInt(System.getProperty("signin.redis.port"));
        LettuceConnectionFactory factory = new LettuceConnectionFactory("127.0.0.1", port);
        factory.afterPropertiesSet();
        factory.start();
        UserDTO user = new UserDTO();
        user.setId(UUID.randomUUID().getMostSignificantBits() & Long.MAX_VALUE);
        UserHolder.saveUser(user);
        try {
            StringRedisTemplate redis = new StringRedisTemplate(factory);
            String prefix = "sign:" + user.getId() + ":";
            var service = serviceAt(redis, "2026-10-08T04:00:00Z");
            assertThat(service.stats().monthlyDays()).isZero();
            for (long offset : new long[]{0, 2, 5, 6, 7}) {
                redis.opsForValue().setBit(prefix + "202610", offset, true);
            }
            for (long offset : new long[]{0, 28, 29}) {
                redis.opsForValue().setBit(prefix + "202609", offset, true);
            }
            var stats = service.stats();
            assertThat(stats.monthlyDays()).isEqualTo(5);
            assertThat(stats.continuousDays()).isEqualTo(3);
            assertThat(stats.previousMonthDays()).isEqualTo(3);
            assertThat(stats.monthDifference()).isEqualTo(2);
            assertThat(service.sign().alreadySigned()).isTrue();
            assertThat(redis.getExpire(prefix + "202610")).isEqualTo(-1);
            assertThat(redis.opsForValue().size(prefix + "202610")).isEqualTo(1L);

            var ninthDay = serviceAt(redis, "2026-10-09T04:00:00Z");
            try (var executor = Executors.newFixedThreadPool(8)) {
                var tasks = IntStream.range(0, 16)
                        .<java.util.concurrent.Callable<Boolean>>mapToObj(index -> () -> {
                            UserHolder.saveUser(user);
                            try { return ninthDay.sign().alreadySigned(); }
                            finally { UserHolder.removeUser(); }
                        }).toList();
                int newlySigned = 0;
                for (var future : executor.invokeAll(tasks, 10, TimeUnit.SECONDS)) {
                    if (!future.get()) newlySigned++;
                }
                assertThat(newlySigned).isEqualTo(1);
            }
            assertThat(ninthDay.stats().monthlyDays()).isEqualTo(6);
            assertThat(ninthDay.stats().continuousDays()).isEqualTo(4);

            for (int offset = 0; offset < 31; offset++) redis.opsForValue().setBit(prefix + "202612", offset, true);
            assertThat(serviceAt(redis, "2026-12-31T04:00:00Z").stats().continuousDays()).isEqualTo(31);
            var january = serviceAt(redis, "2026-12-31T16:00:00Z");
            january.sign();
            assertThat(january.stats().continuousDays()).isEqualTo(1);
            assertThat(january.stats().previousMonthDays()).isEqualTo(31);

            for (int offset = 0; offset < 29; offset++) redis.opsForValue().setBit(prefix + "202802", offset, true);
            var march = serviceAt(redis, "2028-03-01T04:00:00Z");
            assertThat(march.stats().previousMonthDays()).isEqualTo(29);
            assertThat(march.stats().continuousDays()).isZero();
            UserDTO other = new UserDTO();
            other.setId(user.getId() ^ 1L);
            UserHolder.saveUser(other);
            assertThat(service.stats().monthlyDays()).isZero();
        } finally {
            UserHolder.removeUser();
            factory.destroy();
        }
    }

    private static SignService serviceAt(StringRedisTemplate redis, String instant) {
        return new SignServiceImpl(redis, Clock.fixed(Instant.parse(instant), ZoneOffset.UTC));
    }
}

package com.dianping.service;

import com.dianping.dto.UserDTO;
import com.dianping.service.impl.SignServiceImpl;
import com.dianping.utils.UserHolder;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ValueOperations;
import org.springframework.dao.DataAccessResourceFailureException;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.List;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class SignServiceTest {
    private final StringRedisTemplate redis = mock(StringRedisTemplate.class);
    @SuppressWarnings("unchecked")
    private final ValueOperations<String, String> values = mock(ValueOperations.class);

    @BeforeEach
    void setUp() {
        when(redis.opsForValue()).thenReturn(values);
        UserDTO user = new UserDTO();
        user.setId(1001L);
        UserHolder.saveUser(user);
    }

    @AfterEach
    void clearUser() { UserHolder.removeUser(); }

    private SignService serviceAt(String instant) {
        return new SignServiceImpl(redis, Clock.fixed(Instant.parse(instant), ZoneOffset.UTC));
    }

    @Test
    void usesShanghaiDateAndReturnsOldBitForRepeatedSignIn() {
        when(values.setBit("sign:1001:202610", 7L, true)).thenReturn(false, true);
        SignService service = serviceAt("2026-10-07T16:00:00Z");
        assertThat(service.sign().date()).isEqualTo("2026-10-08");
        assertThat(service.sign().alreadySigned()).isTrue();
    }

    @Test
    void countsSetDaysAndTrailingStreakFromToday() {
        when(values.bitField(eq("sign:1001:202610"), any())).thenReturn(List.of(167L));
        when(values.bitField(eq("sign:1001:202609"), any())).thenReturn(List.of(7L));
        var stats = serviceAt("2026-10-08T04:00:00Z").stats();
        assertThat(stats.month()).isEqualTo("202610");
        assertThat(stats.todaySigned()).isTrue();
        assertThat(stats.monthlyDays()).isEqualTo(5);
        assertThat(stats.continuousDays()).isEqualTo(3);
        assertThat(stats.previousMonthDays()).isEqualTo(3);
        assertThat(stats.monthDifference()).isEqualTo(2);
    }

    @Test
    void unsignedTodayDoesNotContinueYesterdaysStreak() {
        when(values.bitField(eq("sign:1001:202610"), any())).thenReturn(List.of(166L));
        when(values.bitField(eq("sign:1001:202609"), any())).thenReturn(List.of(31L));
        var stats = serviceAt("2026-10-08T04:00:00Z").stats();
        assertThat(stats.todaySigned()).isFalse();
        assertThat(stats.monthlyDays()).isEqualTo(4);
        assertThat(stats.continuousDays()).isZero();
        assertThat(stats.monthDifference()).isEqualTo(-1);
    }

    @Test
    void comparesJanuaryWithPreviousYearAndDoesNotContinueAcrossMonths() {
        when(values.bitField(eq("sign:1001:202701"), any())).thenReturn(List.of(1L));
        when(values.bitField(eq("sign:1001:202612"), any())).thenReturn(List.of(2147483647L));
        var stats = serviceAt("2026-12-31T16:00:00Z").stats();
        assertThat(stats.month()).isEqualTo("202701");
        assertThat(stats.continuousDays()).isEqualTo(1);
        assertThat(stats.previousMonthDays()).isEqualTo(31);
        assertThat(stats.monthDifference()).isEqualTo(-30);
    }

    @Test
    void countsAll31DaysWithoutSignedIntegerOverflow() {
        when(values.bitField(eq("sign:1001:202610"), any())).thenReturn(List.of(2147483647L));
        when(values.bitField(eq("sign:1001:202609"), any())).thenReturn(List.of(0L));
        var stats = serviceAt("2026-10-31T04:00:00Z").stats();
        assertThat(stats.monthlyDays()).isEqualTo(31);
        assertThat(stats.continuousDays()).isEqualTo(31);
    }

    @Test
    void missingMonthsAreZero() {
        when(values.bitField(anyString(), any())).thenReturn(List.of(0L));
        var stats = serviceAt("2026-10-08T04:00:00Z").stats();
        assertThat(stats.todaySigned()).isFalse();
        assertThat(stats.monthlyDays()).isZero();
        assertThat(stats.continuousDays()).isZero();
        assertThat(stats.previousMonthDays()).isZero();
        assertThat(stats.monthDifference()).isZero();
    }

    @Test
    void redisFailureIsNotTreatedAsZeroSignIns() {
        when(values.bitField(anyString(), any())).thenThrow(new DataAccessResourceFailureException("offline"));
        assertThatThrownBy(() -> serviceAt("2026-10-08T04:00:00Z").stats())
                .isInstanceOf(DataAccessResourceFailureException.class);
    }

    @Test
    void missingRedisAcknowledgementIsNotTreatedAsSuccessfulSignInOrZeroStats() {
        when(values.setBit(anyString(), anyLong(), eq(true))).thenReturn(null);
        when(values.bitField(anyString(), any())).thenReturn(null);
        SignService service = serviceAt("2026-10-08T04:00:00Z");
        assertThatThrownBy(service::sign).isInstanceOf(DataAccessResourceFailureException.class);
        assertThatThrownBy(service::stats).isInstanceOf(DataAccessResourceFailureException.class);
    }

    @Test
    void anonymousUserCannotWriteSignIn() {
        UserHolder.removeUser();
        assertThatThrownBy(() -> serviceAt("2026-10-08T04:00:00Z").sign())
                .isInstanceOf(org.springframework.security.authentication.AuthenticationCredentialsNotFoundException.class);
        verifyNoInteractions(values);
    }
}

