    private void shop(long id, long type, Double x, Double y) {
        jdbc.update("INSERT INTO tb_shop(id,name,type_id,x,y,score,comments) VALUES(?,?,?,?,?,49,999)",id,"店铺"+id,type,x,y);
    }
    /**
